import { Book } from "@/lib/types";

export const _1corinthians: Book = {
  id: "1corinthians",
  name: "1. Korinther",
  shortName: "1.Kor",
  testament: "new",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Paulus, berufener Apostel* Christi Jesu durch Gottes Willen*, und Sosthenes*, der Bruder,", heading: "Verfasser, Empfänger und Gruß", footnotes: ["d. h. Gesandter, o. Bote\n℘ Röm 1,1", "℘ 2Kor 1,1; Eph 1,1; Kol 1,1; 2Tim 1,1", "℘ Apg 18,17"] },
      { number: 2, text: "an die Gemeinde* Gottes, die in Korinth* ist, den Geheiligten in Christus Jesus*, den berufenen Heiligen*, samt allen, die an jedem Ort den Namen unseres Herrn Jesus Christus anrufen*, ihres und unseres <Herrn>.", footnotes: ["o. Versammlung", "℘ Apg 18,1", "℘ Kap. 6,11; Eph 1,1; Phil 1,1; Kol 1,2; 1Thes 1,1; 2Thes 1,1", "℘ Röm 1,7", "℘ Apg 9,14"] },
      { number: 3, text: "Gnade euch und Friede von Gott, unserem Vater, und dem Herrn Jesus Christus*!", footnotes: ["℘ Röm 1,7"] },
      { number: 4, text: "Ich danke meinem Gott allezeit euretwegen* für die Gnade Gottes, die euch gegeben ist in Christus Jesus:", heading: "Dank für die den Korinthern zuteilgewordene Gnade", footnotes: ["℘ Röm 1,8"] },
      { number: 5, text: "In ihm seid ihr in allem reich gemacht worden, in allem Wort* und aller Erkenntnis*,", footnotes: ["o. Rede", "℘ Kap. 12,8; 2Kor 8,7"] },
      { number: 6, text: "wie denn das Zeugnis des Christus unter* euch gefestigt worden ist.", footnotes: ["o. in"] },
      { number: 7, text: "Daher habt ihr an keiner Gnadengabe* Mangel, während ihr das Offenbarwerden unseres Herrn Jesus Christus erwartet*,", footnotes: ["griech. charisma; d. h. einfach »Gabe« oder »Geschenk«; im NT ist meist eine Gabe Gottes bzw. des Geistes gemeint", "℘ 1Thes 1,10; Tit 2,13"] },
      { number: 8, text: "der euch auch festigen wird bis ans Ende*, <so dass ihr> untadelig <seid>* an dem Tag unseres Herrn Jesus Christus*.", footnotes: ["℘ Röm 16,25", "℘ Jud 24", "℘ Kap. 1,8; 5,5; 2Kor 1,14; Phil 1,6"] },
      { number: 9, text: "Gott ist treu*, durch den ihr berufen worden seid in die Gemeinschaft seines Sohnes Jesus Christus, unseres Herrn*.", footnotes: ["℘ Kap. 10,13; 1Thes 5,24; 2Thes 3,3; Hebr 10,23", "℘ 1Jo 1,3"] },
      { number: 10, text: "Ich ermahne* euch aber, Brüder, durch den Namen unseres Herrn Jesus Christus, dass ihr alle einmütig redet* und nicht Spaltungen unter euch seien*, sondern dass ihr in demselben Sinn* und in derselben Meinung völlig zusammengefügt seiet*.", heading: "Warnung vor Parteisucht und falsch verstandener Weisheit", footnotes: ["o. bitte", "w. dasselbe sagt", "℘ Kap. 12,25", "o. in demselben Denken; o. in derselben Gesinnung", "℘ Röm 12,16; 2Kor 13,11"] },
      { number: 11, text: "Denn es ist mir durch die <Hausgenossen> der Chloë über euch bekannt geworden, meine Brüder, dass Streitigkeiten unter euch sind*.", footnotes: ["℘ Kap. 3,3; 11,18; 2Kor 12,20"] },
      { number: 12, text: "Ich meine aber dies, dass jeder von euch sagt: Ich bin des Paulus, ich aber des Apollos*, ich aber des Kephas*, ich aber Christi*.", footnotes: ["℘ Apg 18,24", "griech. petros; lat. petrus\n℘ Kap. 3,4.22; Joh 1,42", "℘ 2Kor 10,7"] },
      { number: 13, text: "Ist der Christus zerteilt? Ist etwa Paulus für euch gekreuzigt, oder seid ihr auf den Namen des Paulus getauft worden?" },
      { number: 14, text: "Ich danke Gott, dass ich niemand von euch getauft habe außer Krispus* und Gajus*,", footnotes: ["℘ Apg 18,8", "℘ Röm 16,23"] },
      { number: 15, text: "damit nicht jemand sage, ihr seiet auf meinen Namen getauft worden." },
      { number: 16, text: "Ich habe aber auch das Haus des Stephanas* getauft; sonst weiß ich nicht, ob ich noch jemand getauft habe.", footnotes: ["℘ Kap. 16,15"] },
      { number: 17, text: "Denn Christus hat mich nicht ausgesandt zu taufen, sondern das Evangelium zu verkündigen*: nicht in Redeweisheit*, damit nicht das Kreuz Christi zunichte gemacht werde.", footnotes: ["℘ Apg 26,16-18", "℘ Kap. 2,1.4.13"] },
      { number: 18, text: "Denn das Wort vom Kreuz ist denen, die verloren gehen, Torheit*; uns aber, die wir gerettet werden, ist es Gottes Kraft*.", footnotes: ["℘ Kap. 2,14; 2Kor 4,3", "℘ Röm 1,16"] },
      { number: 19, text: "Denn es steht geschrieben: »Ich werde die Weisheit der Weisen vernichten, und den Verstand der Verständigen werde ich verwerfen*.«*", footnotes: ["o. zunichte machen", "℘ Jes 29,14"] },
      { number: 20, text: "Wo ist ein Weiser? Wo ein Schriftgelehrter? Wo ein Wortstreiter dieses Zeitalters*? Hat nicht Gott die Weisheit der Welt zur Torheit gemacht*?", footnotes: ["o. dieser Welt (griech. Äon); im Unterschied zu »Welt« in V. 20b—27, wo griech. Kosmos steht", "℘ Kap. 2,6; 3,19; Hi 12,17; Jes 19,11.12; 44,25; Röm 1,22"] },
      { number: 21, text: "Denn weil in der Weisheit Gottes die Welt durch die Weisheit Gott nicht erkannte*, hat es Gott wohlgefallen, durch die Torheit der Predigt die Glaubenden zu retten*.", footnotes: ["℘ Joh 17,25", "℘ Kap. 15,2"] },
      { number: 22, text: "Und weil denn Juden Zeichen fordern* und Griechen* Weisheit suchen,", footnotes: ["℘ Mt 12,38; Joh 4,48", "Darunter konnten alle griech. sprechenden und griech. beeinflussten nichtjüd. Menschen des östl. Mittelmeerraumes verstanden werden; hier ist der Begriff aber wohl auf alle Menschen, die nicht unter jüd. Gesetz stehen, erweitert worden."] },
      { number: 23, text: "predigen wir Christus als gekreuzigt*, den Juden ein Ärgernis* und den Nationen eine Torheit*;", footnotes: ["℘ Kap. 2,2", "o. etwas Anstößiges; o. ein Anlass zur Sünde\n℘ Röm 9,32.33; Gal 5,11", "℘ Kap. 2,14"] },
      { number: 24, text: "den Berufenen selbst aber, Juden wie Griechen*, Christus, Gottes Kraft* und Gottes Weisheit*.", footnotes: ["Darunter konnten alle griech. sprechenden und griech. beeinflussten nichtjüd. Menschen des östl. Mittelmeerraumes verstanden werden; hier ist der Begriff aber wohl auf alle Menschen, die nicht unter jüd. Gesetz stehen, erweitert worden.\n℘ Röm 9,24", "℘ Kap. 2,4.5; Röm 1,16", "℘ Kol 2,3"] },
      { number: 25, text: "Denn das Törichte Gottes ist weiser als die Menschen, und das Schwache Gottes ist stärker als die Menschen." },
      { number: 26, text: "Denn seht, eure Berufung, Brüder, dass es nicht viele Weise nach dem Fleisch*, nicht viele Mächtige, nicht viele Edle sind;", footnotes: ["℘ Mt 11,25; Joh 7,48"] },
      { number: 27, text: "sondern das Törichte der Welt hat Gott auserwählt*, damit er die Weisen zuschanden mache; und das Schwache der Welt hat Gott auserwählt, damit er das Starke zuschanden mache*.", footnotes: ["℘ Jak 2,5", "℘ Apg 4,13"] },
      { number: 28, text: "Und das Unedle der Welt und das Verachtete hat Gott auserwählt, das, was nicht ist, damit er das, was ist, zunichte mache*,", footnotes: ["℘ 1Sam 2,8"] },
      { number: 29, text: "dass sich vor Gott kein Fleisch rühme*.", footnotes: ["℘ Röm 3,27; Eph 2,9"] },
      { number: 30, text: "Aus ihm aber <kommt es, dass> ihr in Christus Jesus seid*, der uns geworden ist Weisheit von Gott* und Gerechtigkeit* und Heiligkeit* und Erlösung*;", footnotes: ["℘ Röm 8,1", "℘ Kol 2,3", "℘ Kap. 6,11; 2Kor 5,21", "o. Heiligung, Geheiligtsein\n℘ Joh 17,19; Hebr 10,10", "℘ Eph 1,7; Kol 1,14"] },
      { number: 31, text: "damit, wie geschrieben steht: »Wer sich rühmt, der rühme sich des Herrn*!«*", footnotes: ["o. im Herrn", "℘ Jes 45,25; Jer 9,23; 2Kor 10,17; Gal 6,14"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "Und ich, als ich zu euch kam*, Brüder, kam nicht, um euch mit Vortrefflichkeit der Rede* oder Weisheit das Geheimnis* Gottes zu verkündigen*.", heading: "Der Apostel predigt die Weisheit Gottes", footnotes: ["℘ Apg 18,1", "℘ 2Kor 11,6", "℘ Kap. 1,17; 1Jo 5,9.10", "w. kam nicht nach Vortrefflichkeit der Rede oder Weisheit euch das Geheimnis Gottes verkündigend"] },
      { number: 2, text: "Denn ich nahm mir vor, nichts anderes unter euch zu wissen als nur Jesus Christus, und ihn als gekreuzigt*.", footnotes: ["℘ Kap. 1,23; Gal 3,1; 6,14"] },
      { number: 3, text: "Und ich war bei euch in Schwachheit* und mit Furcht und in vielem Zittern*;", footnotes: ["℘ Gal 4,13", "℘ Apg 18,9; 2Kor 10,10"] },
      { number: 4, text: "und meine Rede und meine Predigt <bestand> nicht in überredenden Worten der Weisheit*, sondern in Erweisung des Geistes und der Kraft*,", footnotes: ["℘ Kap. 1,17", "℘ Kap. 4,20; Apg 6,8; 2Kor 3,3"] },
      { number: 5, text: "damit euer Glaube nicht auf Menschenweisheit, sondern auf Gottes Kraft beruhe*.", footnotes: ["℘ Kap. 1,24; 2Kor 4,7; Eph 1,19; 1Thes 1,5"] },
      { number: 6, text: "Wir reden aber Weisheit* unter den Vollkommenen, jedoch nicht Weisheit dieses Zeitalters*, auch nicht der Fürsten dieses Zeitalters*, die zunichte werden*,", footnotes: ["℘ Kap. 12,8; Kol 1,28", "griech. Äon", "griech. Äon", "℘ Kap. 1,20"] },
      { number: 7, text: "sondern wir reden Gottes Weisheit in einem Geheimnis, die verborgene, die Gott vorherbestimmt hat, vor den Zeitaltern*, zu unserer Herrlichkeit*.", footnotes: ["griech. Äonen", "℘ Röm 16,25; Kol 1,26"] },
      { number: 8, text: "Keiner von den Fürsten dieses Zeitalters* hat sie erkannt — denn wenn sie <sie> erkannt hätten, so würden sie wohl den Herrn der Herrlichkeit* nicht gekreuzigt haben* —,", footnotes: ["griech. Äon", "℘ Jak 2,1", "℘ Apg 13,27"] },
      { number: 9, text: "sondern wie geschrieben steht: »Was kein Auge gesehen und kein Ohr gehört hat und in keines Menschen Herz gekommen ist, was Gott denen bereitet hat, die ihn lieben.«*", footnotes: ["℘ Jes 64,3; 52,15; Ri 5,31; Jak 2,5"] },
      { number: 10, text: "Uns aber hat Gott es offenbart durch den Geist*, denn der Geist erforscht alles, auch die Tiefen Gottes.", footnotes: ["℘ Joh 16,13"] },
      { number: 11, text: "Denn wer von den Menschen weiß, was im* Menschen ist, als nur der Geist des Menschen, der in ihm ist? So hat auch niemand erkannt, was in Gott* ist, als nur der Geist Gottes*.", footnotes: ["w. des", "w. Gottes", "℘ Röm 11,34"] },
      { number: 12, text: "Wir aber haben nicht den Geist der Welt empfangen, sondern den Geist, der aus Gott ist*, damit wir die <Dinge> kennen, die uns von Gott geschenkt sind*.", footnotes: ["℘ Röm 8,15", "℘ Joh 16,14; 1Jo 5,20"] },
      { number: 13, text: "Davon reden wir auch, nicht in Worten, gelehrt durch menschliche Weisheit*, sondern in <Worten>, gelehrt durch den Geist*, indem wir Geistliches durch Geistliches deuten.", footnotes: ["℘ Kap. 1,17; 2Kor 1,12", "℘ 1Petr 4,11"] },
      { number: 14, text: "Ein natürlicher* Mensch* aber nimmt nicht an, was des Geistes Gottes ist*, denn es ist ihm eine Torheit*, und er kann es nicht erkennen*, weil es geistlich beurteilt* wird.", footnotes: ["w. seelischer", "℘ Jud 19", "℘ Joh 8,43.47", "℘ Kap. 1,18.23", "℘ Röm 8,7", "o. unterschieden; so auch V. 15"] },
      { number: 15, text: "Der geistliche* <Mensch> dagegen beurteilt* zwar alles*, er selbst jedoch wird von niemand beurteilt.", footnotes: ["℘ Kap. 3,1", "o. unterscheidet", "℘ 1Jo 2,20.27"] },
      { number: 16, text: "Denn »wer hat den Sinn* des Herrn erkannt, dass er ihn unterweisen könnte?«* Wir aber haben Christi Sinn*.", footnotes: ["o. Denken", "℘ Jes 40,13.14; Röm 11,34", "o. Denken"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Und ich, Brüder, konnte nicht zu euch reden als zu Geistlichen*, sondern als zu Fleischlichen, als zu Unmündigen in Christus*.", heading: "Erneute Warnung vor Parteisucht — Dienende Stellung der Lehrer in der Gemeinde als Mitarbeiter Gottes", footnotes: ["℘ Kap. 2,15; Gal 6,1", "℘ Eph 4,14"] },
      { number: 2, text: "Ich habe euch Milch zu trinken gegeben, nicht feste Speise*; denn ihr konntet <sie> noch nicht <vertragen>. Ihr könnt es aber auch jetzt noch nicht,", footnotes: ["℘ Hebr 5,12.13"] },
      { number: 3, text: "denn ihr seid noch fleischlich*. Denn wo Eifersucht* und Streit unter euch ist*, seid ihr da nicht fleischlich und wandelt nach Menschenweise*?", footnotes: ["℘ Röm 7,14", "o. Neid; o. Rivalität", "℘ Kap. 1,11", "℘ Jak 3,14.15"] },
      { number: 4, text: "Denn wenn einer sagt: Ich bin des Paulus, der andere aber: Ich des Apollos* — seid ihr nicht menschlich*?", footnotes: ["℘ Kap. 1,12", "w. Menschen"] },
      { number: 5, text: "Was ist denn Apollos? Und was ist Paulus? Diener*, durch die ihr gläubig geworden seid, und zwar wie der Herr einem jeden gegeben hat*.", footnotes: ["℘ Kap. 4,1", "℘ 2Kor 4,5"] },
      { number: 6, text: "Ich habe gepflanzt*, Apollos hat begossen*, Gott aber hat das Wachstum gegeben.", footnotes: ["℘ Apg 18,4.11", "℘ Apg 18,24.27"] },
      { number: 7, text: "So ist weder der da pflanzt etwas, noch der da begießt, sondern Gott, der das Wachstum gibt*.", footnotes: ["℘ Gal 6,3"] },
      { number: 8, text: "Der aber pflanzt und der begießt, sind eins; jeder aber wird seinen eigenen Lohn empfangen nach seiner eigenen Arbeit*.", footnotes: ["o. Mühe\n℘ Kap. 4,5; Ps 62,13; Mt 20,4; Joh 4,36"] },
      { number: 9, text: "Denn Gottes Mitarbeiter sind wir; Gottes Ackerfeld, Gottes Bau seid ihr*.", footnotes: ["℘ Eph 2,21.22"] },
      { number: 10, text: "Nach der Gnade Gottes, die mir gegeben ist*, habe ich als ein weiser Baumeister den Grund gelegt; ein anderer aber baut darauf; jeder aber sehe zu, wie er darauf baut.", footnotes: ["℘ Kap. 15,10; Röm 1,5"] },
      { number: 11, text: "Denn einen anderen Grund kann niemand legen außer dem, der gelegt ist*, welcher ist Jesus Christus*.", footnotes: ["o. liegt", "℘ Apg 4,11; Eph 2,20"] },
      { number: 12, text: "Wenn aber jemand auf den Grund Gold, Silber, kostbare Steine, Holz, Heu, Stroh baut," },
      { number: 13, text: "so wird das Werk eines jeden offenbar werden, denn der Tag wird es klarmachen, weil er in Feuer offenbart wird. Und wie das Werk eines jeden beschaffen ist, das wird das Feuer erweisen." },
      { number: 14, text: "Wenn jemandes Werk bleiben wird, das er darauf gebaut hat, so wird er Lohn empfangen*;", footnotes: ["℘ 2Jo 8"] },
      { number: 15, text: "wenn jemandes Werk verbrennen wird, so wird er Schaden leiden, er selbst aber wird gerettet werden, doch so wie durchs Feuer." },
      { number: 16, text: "Wisst ihr nicht, dass ihr Gottes Tempel seid* und der Geist Gottes in* euch wohnt*?", footnotes: ["℘ 2Kor 6,16; Eph 2,21; Offb 3,12", "o. unter", "℘ Kap. 6,19; Joh 14,17"] },
      { number: 17, text: "Wenn jemand den Tempel Gottes verdirbt, den wird Gott verderben*; denn der Tempel Gottes ist heilig, und der seid ihr.", footnotes: ["℘ Hes 5,11; Gal 5,10"] },
      { number: 18, text: "Niemand betrüge sich selbst*! Wenn jemand unter euch meint, weise zu sein in dieser Welt*, so werde er töricht, damit er weise werde.", footnotes: ["℘ Gal 6,3", "o. in diesem Zeitalter (griech. Äon)"] },
      { number: 19, text: "Denn die Weisheit dieser Welt* ist Torheit bei Gott*; denn es steht geschrieben: »Der die Weisen fängt in ihrer List.«*", footnotes: ["griech. Kosmos; ein anderes Wort als in V. 18", "℘ Kap. 1,20", "℘ Hi 5,13"] },
      { number: 20, text: "Und wieder: »Der Herr kennt die Überlegungen der Weisen, dass sie nichtig sind.«*", footnotes: ["℘ Ps 94,11"] },
      { number: 21, text: "So rühme sich denn niemand <im Blick auf> Menschen*, denn alles ist euer.", footnotes: ["w. in Menschen"] },
      { number: 22, text: "Es sei Paulus oder Apollos oder Kephas*, es sei Welt oder Leben oder Tod, es sei Gegenwärtiges oder Zukünftiges*; alles ist euer,", footnotes: ["griech. petros; lat. petrus\n℘ Kap. 1,12", "℘ Röm 8,38"] },
      { number: 23, text: "ihr aber seid Christi*, Christus aber ist Gottes*.", footnotes: ["℘ Röm 14,8", "℘ Kap. 11,3"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Dafür halte man uns: für Diener Christi* und Verwalter* der Geheimnisse Gottes*.", heading: "Die Apostel sind Vorbilder im Dienst und Leiden für Christus", footnotes: ["℘ Kap. 3,5; 2Kor 6,4", "℘ Tit 1,7; 1Petr 4,10", "℘ Kol 1,25.26"] },
      { number: 2, text: "Übrigens sucht man hier an den Verwaltern, dass einer treu befunden werde*.", footnotes: ["℘ Mt 25,23; Lk 12,42"] },
      { number: 3, text: "Mir aber ist es das Geringste, dass ich von euch oder von einem menschlichen <Gerichts>tag beurteilt werde; ich beurteile mich aber auch selbst nicht." },
      { number: 4, text: "Denn ich bin mir keiner Schuld* bewusst, aber dadurch bin ich nicht gerechtfertigt. Der mich aber beurteilt, ist der Herr*.", footnotes: ["w. nichts", "℘ Röm 14,4"] },
      { number: 5, text: "So verurteilt nichts vor der Zeit*, bis der Herr kommt, der auch das Verborgene der Finsternis ans Licht bringen* und die Absichten der Herzen offenbaren wird*! Und dann wird jedem sein Lob werden von Gott*.", footnotes: ["℘ Mt 7,1; Röm 14,10", "℘ Ps 90,8; 1Tim 5,25", "℘ Röm 2,16", "℘ Kap. 3,8; 2Kor 5,10"] },
      { number: 6, text: "Dies aber, Brüder, habe ich auf mich und Apollos bezogen um euretwillen*, damit ihr an uns lernt, nicht über das hinaus <zu denken>, was geschrieben ist, damit ihr euch nicht aufbläht für den einen gegen den anderen*.", footnotes: ["℘ Kap. 3,4-7", "℘ 2Kor 12,20"] },
      { number: 7, text: "Denn wer gibt dir einen Vorrang*? Was aber hast du, das du nicht empfangen hast? Wenn du es aber auch empfangen hast, was rühmst du dich, als hättest du es nicht empfangen?", footnotes: ["o. wer unterscheidet dich; o. wer zeichnet dich aus"] },
      { number: 8, text: "Schon seid ihr satt, schon seid ihr reich geworden*; ihr seid ohne uns zur Herrschaft gekommen. Oh, dass ihr doch <wirklich> zur Herrschaft gekommen wäret, damit auch wir mit euch herrschen könnten!", footnotes: ["℘ Offb 3,17"] },
      { number: 9, text: "Denn mir scheint, dass Gott uns, die Apostel, als die Letzten hingestellt hat, wie zum Tod bestimmt*; denn wir sind der Welt ein Schauspiel geworden*, sowohl Engeln als <auch> Menschen.", footnotes: ["℘ Kap. 15,31; Röm 8,36; 2Kor 6,9", "℘ Hebr 10,33"] },
      { number: 10, text: "Wir sind Narren um Christi willen, ihr aber seid klug in Christus*; wir schwach, ihr aber stark*; ihr geehrt, wir aber verachtet.", footnotes: ["℘ 2Kor 11,19", "℘ 2Kor 13,9"] },
      { number: 11, text: "Bis zur jetzigen Stunde leiden wir sowohl Hunger als <auch> Durst und sind nackt* und werden mit Fäusten geschlagen* und haben keine bestimmte Wohnung*", footnotes: ["℘ 2Kor 11,27", "℘ 2Kor 11,23", "℘ 2Kor 1,5"] },
      { number: 12, text: "und mühen uns ab und arbeiten mit unseren eigenen Händen*. Geschmäht, segnen wir*; verfolgt, dulden wir*;", footnotes: ["℘ Kap. 9,15; Apg 18,3", "℘ Röm 12,14", "℘ Mt 5,44"] },
      { number: 13, text: "gelästert, reden wir gut zu; wie Unrat der Welt sind wir geworden, ein Abschaum aller bis jetzt*.", footnotes: ["℘ Lk 6,22"] },
      { number: 14, text: "Nicht um euch zu beschämen, schreibe ich dies, sondern ich ermahne euch als meine geliebten Kinder*.", footnotes: ["℘ Gal 4,19; 1Thes 2,11"] },
      { number: 15, text: "Denn wenn ihr zehntausend Zuchtmeister in Christus hättet, so doch nicht viele Väter; denn in Christus Jesus habe ich euch gezeugt* durch das Evangelium.", footnotes: ["℘ Kap. 9,1; Phim 10"] },
      { number: 16, text: "Ich bitte* euch nun, seid meine Nachahmer*!", footnotes: ["o. ermahne", "℘ Kap. 11,1; Phil 3,17; 2Thes 3,9"] },
      { number: 17, text: "Deshalb habe ich euch Timotheus gesandt*, der mein geliebtes und treues Kind im Herrn ist*; der wird euch erinnern an meine Wege in Christus, wie ich überall in jeder Gemeinde* lehre*.", footnotes: ["℘ Kap. 16,10; Apg 16,1; Phil 2,19", "℘ 1Tim 1,2; 2Tim 1,2", "o. Versammlung", "℘ Kap. 7,17; 2Tim 3,10"] },
      { number: 18, text: "Einige aber sind aufgeblasen*, als ob ich nicht zu euch kommen würde.", footnotes: ["℘ Kap. 5,2; Kol 2,18; 1Tim 6,4"] },
      { number: 19, text: "Ich werde aber bald zu euch kommen*, wenn der Herr will*, und werde nicht das Wort, sondern die Kraft der Aufgeblasenen kennenlernen.", footnotes: ["℘ 2Kor 1,15", "℘ Kap. 16,7; Apg 18,21"] },
      { number: 20, text: "Denn das Reich* Gottes <besteht> nicht im Wort, sondern in Kraft*.", footnotes: ["o. die Königsherrschaft", "℘ Kap. 2,4"] },
      { number: 21, text: "Was wollt ihr? Soll ich mit der Rute zu euch kommen* oder in Liebe und im Geist der Sanftmut?", footnotes: ["℘ 2Kor 10,2"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "Überhaupt hört man, dass Unzucht* unter euch ist, und <zwar> eine solche Unzucht*, die selbst unter den Nationen nicht <stattfindet>: dass einer seines Vaters Frau hat*.", heading: "Gemeindezucht gegen Sünde in der Gemeinde", footnotes: ["o. Hurerei", "o. Hurerei", "℘ 3Mo 18,8; 5Mo 27,20; 2Kor 12,21"] },
      { number: 2, text: "Und ihr seid aufgeblasen* und habt nicht etwa Leid getragen*, damit der, der diese Tat begangen hat, aus eurer Mitte entfernt würde!", footnotes: ["℘ Kap. 4,18", "℘ 2Kor 7,11"] },
      { number: 3, text: "Denn ich, zwar dem Leibe nach abwesend, aber im Geist anwesend*, habe schon als Anwesender das Urteil gefällt über den, der dieses so verübt hat", footnotes: ["℘ Kol 2,5"] },
      { number: 4, text: "*— wenn ihr und mein Geist mit der Kraft unseres Herrn Jesus versammelt seid* —,", footnotes: ["o. 4 im Namen unseres Herrn Jesus — wenn ihr und mein Geist samt der Kraft unseres Herrn Jesus versammelt seid —, 5 einen solchen dem Satan zu überliefern", "℘ Mt 18,20"] },
      { number: 5, text: "einen solchen im Namen unseres Herrn Jesus dem Satan zu überliefern* zum Verderben des Fleisches, damit der Geist gerettet werde am Tage des Herrn*.", footnotes: ["o. 4 im Namen unseres Herrn Jesus — wenn ihr und mein Geist samt der Kraft unseres Herrn Jesus versammelt seid —, 5 einen solchen dem Satan zu überliefern\n℘ 1Tim 1,20", "℘ Kap. 1,8"] },
      { number: 6, text: "Euer Rühmen ist nicht gut*. Wisst ihr nicht, dass ein wenig Sauerteig den ganzen Teig durchsäuert*?", footnotes: ["℘ Jak 4,16", "℘ Mt 13,33; Gal 5,9"] },
      { number: 7, text: "Fegt den alten Sauerteig aus*, damit ihr ein neuer Teig seid, wie ihr <ja bereits> ungesäuert seid! Denn auch unser Passah<lamm>, Christus, ist geschlachtet*.", footnotes: ["℘ 2Mo 13,7", "℘ 2Mo 12,21; Offb 5,6"] },
      { number: 8, text: "Darum lasst uns das Fest feiern, nicht mit altem Sauerteig, auch nicht mit Sauerteig der Bosheit und Schlechtigkeit*, sondern mit Ungesäuertem der Lauterkeit und Wahrheit*!", footnotes: ["℘ Lk 12,1", "℘ 2Mo 12,15-20"] },
      { number: 9, text: "Ich habe euch in dem Brief geschrieben, nicht mit Unzüchtigen* Umgang zu haben;", footnotes: ["o. Hurern; so auch V. 10.11"] },
      { number: 10, text: "nicht überhaupt mit den Unzüchtigen dieser Welt oder den Habsüchtigen und Räubern oder Götzendienern, sonst müsstet ihr ja aus der Welt hinausgehen*.", footnotes: ["℘ Joh 17,15"] },
      { number: 11, text: "Nun aber habe ich euch geschrieben, keinen Umgang zu haben, wenn jemand, der Bruder genannt wird, ein Unzüchtiger ist oder ein Habsüchtiger oder ein Götzendiener oder ein Lästerer oder ein Trunkenbold oder ein Räuber; mit einem solchen nicht einmal zu essen*.", footnotes: ["℘ Röm 16,17"] },
      { number: 12, text: "Denn was habe ich zu richten, die draußen sind*? Richtet ihr nicht, die drinnen sind?", footnotes: ["℘ Mk 4,11"] },
      { number: 13, text: "Die aber draußen sind, richtet Gott. Tut den Bösen von euch selbst hinaus*!", footnotes: ["℘ 5Mo 13,6; Mt 18,17"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "Bringt es jemand von euch, der einen Rechtsstreit mit dem anderen hat, über sich, vor den Ungerechten zu streiten und nicht vor den Heiligen?", heading: "Rechtsstreit unter Gemeindegliedern gehört nicht vor Gericht" },
      { number: 2, text: "Oder wisst ihr nicht, dass die Heiligen die Welt richten werden*? Und wenn durch euch* die Welt gerichtet wird, seid ihr dann nicht würdig, über die geringsten Dinge zu richten*?", footnotes: ["℘ Dan 7,22; Offb 2,26; 20,4", "o. vor euch (d. i. in eurem Beisein)", "w. seid ihr <dann etwa> unwürdig der geringsten Gerichte"] },
      { number: 3, text: "Wisst ihr nicht, dass wir Engel richten werden*, wie viel mehr <über> Alltägliches?", footnotes: ["℘ 2Petr 2,4"] },
      { number: 4, text: "Wenn ihr nun über alltägliche Dinge Rechtshändel habt, so setzt ihr die <zu Richtern> ein, die in der Gemeinde* nichts gelten?*", footnotes: ["o. Versammlung", "o. so setzt <doch> die <zu Richtern> ein, die in der Gemeinde nichts gelten!"] },
      { number: 5, text: "Zur Beschämung sage ich es euch*. Also gar kein Weiser ist unter euch, der zwischen Bruder und Bruder* entscheiden* kann?", footnotes: ["℘ Kap. 15,34", "w. zwischen seinem Bruder", "o. unterscheiden"] },
      { number: 6, text: "Sondern es streitet Bruder mit Bruder, und das vor Ungläubigen!" },
      { number: 7, text: "Es ist nun schon überhaupt ein Fehler an euch, dass ihr Rechtshändel miteinander habt*. Warum lasst ihr euch nicht lieber Unrecht tun? Warum lasst ihr euch nicht lieber übervorteilen*?", footnotes: ["℘ Jak 4,1", "o. berauben; so auch V. 8\n℘ Mt 5,39.40"] },
      { number: 8, text: "Aber ihr selbst tut Unrecht und übervorteilt, und das Brüdern gegenüber!" },
      { number: 9, text: "Oder wisst ihr nicht, dass Ungerechte das Reich* Gottes nicht erben werden? Irrt euch nicht*! Weder Unzüchtige* noch Götzendiener* noch Ehebrecher noch Lustknaben* noch Knabenschänder", footnotes: ["o. die Königsherrschaft", "℘ Gal 6,7; Jak 1,16", "o. Hurer", "℘ Offb 21,8", "w. Weichlinge; gemeint sind Männer, die sich sexuell missbrauchen lassen"] },
      { number: 10, text: "noch Diebe noch Habsüchtige noch Trunkenbolde noch Lästerer noch Räuber* werden das Reich* Gottes erben*.", footnotes: ["℘ Mt 15,19", "o. die Königsherrschaft", "℘ Kap. 15,10; Gal 5,21; Eph 5,5"] },
      { number: 11, text: "Und das sind manche von euch gewesen*; aber ihr seid abgewaschen*, aber ihr seid geheiligt*, aber ihr seid gerechtfertigt worden durch den* Namen des Herrn Jesus Christus* und durch den* Geist unseres Gottes*.", footnotes: ["℘ Tit 3,3", "℘ Joh 13,10; Eph 5,26; 1Jo 1,7.9; Offb 1,5", "℘ 2Thes 2,13; 1Petr 1,2", "o. in dem (d. i. in der Kraft des)", "℘ 1Jo 2,12", "o. in dem (d. i. in der Kraft des)", "℘ Kap. 1,30; Röm 8,30"] },
      { number: 12, text: "Alles ist mir erlaubt, aber nicht alles ist nützlich*. Alles ist mir erlaubt, aber ich will mich von nichts beherrschen lassen.", heading: "Warnung vor Unzucht", footnotes: ["℘ Kap. 10,23"] },
      { number: 13, text: "Die Speisen <sind> für den Bauch und der Bauch für die Speisen; Gott aber wird sowohl diesen als auch jene zunichte machen. Der Leib aber <ist> nicht für die Hurerei*, sondern für den Herrn* und der Herr für den Leib.", footnotes: ["℘ Kap. 10,8; Apg 15,20", "℘ Röm 12,1"] },
      { number: 14, text: "Gott aber hat den Herrn auferweckt* und wird auch uns auferwecken* durch seine Macht*.", footnotes: ["℘ Kap. 15,4.20; Apg 2,24", "w. aus-auferwecken (d. h. aus den Toten); so auch Phil 3,11", "℘ Kap. 15,22; Röm 8,11; 2Kor 4,14"] },
      { number: 15, text: "Wisst ihr nicht, dass eure Leiber Glieder Christi sind*? Soll ich denn die Glieder Christi nehmen und zu Gliedern einer Hure machen? Auf keinen Fall!", footnotes: ["℘ Kap. 12,27; Eph 5,30"] },
      { number: 16, text: "Oder wisst ihr nicht, dass, wer der Hure anhängt, ein Leib <mit ihr> ist? »Denn es werden«, heißt es, »die zwei ein* Fleisch sein.«*", footnotes: ["w. zu einem", "℘ 1Mo 2,24; Mt 19,5"] },
      { number: 17, text: "Wer aber dem Herrn anhängt*, ist ein Geist <mit ihm>.", footnotes: ["℘ Ps 63,9"] },
      { number: 18, text: "Flieht die Unzucht*! Jede Sünde, die ein Mensch begehen mag, ist außerhalb des Leibes; wer aber Unzucht* treibt, sündigt gegen den eigenen Leib.", footnotes: ["o. Hurerei\n℘ Kap. 10,8; Apg 15,20", "o. Hurerei"] },
      { number: 19, text: "Oder wisst ihr nicht, dass euer Leib ein Tempel* des Heiligen Geistes in euch ist*, den ihr von Gott habt*, und dass ihr nicht euch selbst gehört*?", footnotes: ["℘ Joh 2,21", "℘ Kap. 3,16", "℘ 1Jo 3,24", "℘ Röm 14,7.8"] },
      { number: 20, text: "Denn ihr seid um einen Preis erkauft worden*. Verherrlicht nun Gott mit* eurem Leib*!", footnotes: ["℘ Kap. 7,23; Apg 20,28; Gal 3,13; 1Petr 1,18.19", "o. in", "℘ Kap. 10,31; Phil 1,20"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "Was aber das betrifft, wovon ihr mir *geschrieben habt, so ist es gut für einen Menschen, keine Frau zu berühren.", heading: "Verhalten in der Ehe", footnotes: ["o. geschrieben habt: »Es ist gut für einen Menschen, keine Frau zu berühren.« 2 Aber wegen der Unzucht soll jeder seine eigene Frau haben"] },
      { number: 2, text: "Aber wegen der Unzucht* habe jeder seine eigene Frau*, und jede habe ihren eigenen Mann.", footnotes: ["o. Hurerei", "o. geschrieben habt: »Es ist gut für einen Menschen, keine Frau zu berühren.« 2 Aber wegen der Unzucht soll jeder seine eigene Frau haben"] },
      { number: 3, text: "Der Mann leiste der Frau die <eheliche> Pflicht*, ebenso aber auch die Frau dem Mann.", footnotes: ["℘ 2Mo 21,10"] },
      { number: 4, text: "Die Frau verfügt nicht über ihren eigenen Leib, sondern der Mann; ebenso aber verfügt auch der Mann nicht über seinen eigenen Leib, sondern die Frau." },
      { number: 5, text: "Entzieht* euch einander nicht, es sei denn nach Übereinkunft eine Zeit lang, damit ihr euch dem Gebet widmet* und dann wieder zusammen seid, damit der Satan euch nicht versuche, weil ihr euch nicht enthalten könnt*.", footnotes: ["o. Beraubt", "℘ 1Petr 3,7", "w. wegen eurer Unenthaltsamkeit"] },
      { number: 6, text: "Dies aber sage ich als Zugeständnis, nicht als Befehl*.", footnotes: ["℘ 2Kor 8,8; Phim 8.9"] },
      { number: 7, text: "Ich wünsche aber, alle Menschen wären wie ich; doch jeder hat seine eigene Gnadengabe* von Gott, der eine so, der andere so*.", footnotes: ["griech. charisma; d. h. einfach »Gabe« oder »Geschenk«; im NT ist meist eine Gabe Gottes bzw. des Geistes gemeint", "℘ Kap. 12,11; Mt 19,11.12"] },
      { number: 8, text: "Ich sage aber den Unverheirateten und den Witwen: Es ist gut für sie, wenn sie bleiben wie ich." },
      { number: 9, text: "Wenn sie sich aber nicht enthalten können, so sollen sie heiraten*, denn es ist besser, zu heiraten, als <vor Verlangen> zu brennen.", footnotes: ["℘ 1Tim 5,14"] },
      { number: 10, text: "Den Verheirateten aber gebiete nicht ich*, sondern der Herr*, dass eine Frau sich nicht vom Mann scheiden lassen soll*", heading: "Über Ehescheidung", footnotes: ["℘ V. 12.25.40", "℘ 1Thes 4,15", "℘ Mt 5,32"] },
      { number: 11, text: "— wenn sie aber doch geschieden ist, so bleibe sie unverheiratet oder versöhne sich mit dem Mann — und dass ein Mann seine Frau nicht entlasse*.", footnotes: ["℘ Mal 2,16; Mt 19,6.8.9"] },
      { number: 12, text: "Den Übrigen aber sage ich*, nicht der Herr: Wenn ein Bruder eine ungläubige Frau hat und sie willigt ein, bei ihm zu wohnen, so entlasse er sie nicht.", footnotes: ["℘ V. 10"] },
      { number: 13, text: "Und eine Frau, die einen ungläubigen Mann* hat, und der willigt ein, bei ihr zu wohnen, entlasse den Mann nicht.", footnotes: ["℘ 1Petr 3,1"] },
      { number: 14, text: "Denn der ungläubige Mann ist durch die* Frau geheiligt, und die ungläubige Frau ist durch den* Bruder geheiligt; sonst wären ja eure Kinder unrein, nun aber sind sie heilig.", footnotes: ["o. in der/dem", "o. in der/dem"] },
      { number: 15, text: "Wenn aber der Ungläubige sich scheidet, so scheide er sich. Der Bruder oder die Schwester ist in solchen <Fällen> nicht gebunden*; zum Frieden hat uns* Gott doch berufen.", footnotes: ["w. versklavt", "mit anderen Handschr.: euch"] },
      { number: 16, text: "Denn was weißt du, Frau, ob du den Mann retten wirst? Oder was weißt du, Mann, ob du die Frau retten wirst?" },
      { number: 17, text: "Doch wie der Herr einem jeden zugeteilt hat, wie Gott einen jeden berufen hat, so wandle er; und so verordne ich es in allen Gemeinden*.", heading: "Bedeutungslosigkeit des Standes für die Berufung durch Gott", footnotes: ["o. Versammlungen\n℘ Kap. 4,17"] },
      { number: 18, text: "Ist jemand beschnitten berufen worden, so bleibe er bei der Beschneidung; ist jemand unbeschnitten berufen worden, so lasse er sich nicht beschneiden." },
      { number: 19, text: "Die Beschneidung ist nichts, und das Unbeschnittensein ist nichts*, sondern das Halten der Gebote Gottes*.", footnotes: ["℘ Röm 2,28.29; Gal 5,6", "℘ Joh 14,23.24"] },
      { number: 20, text: "Jeder bleibe in dem Stand*, in dem er berufen worden ist.", footnotes: ["w. in der Berufung, in der"] },
      { number: 21, text: "Bist du als Sklave berufen worden, so lass es dich nicht kümmern; wenn du aber auch frei werden kannst, mach umso lieber Gebrauch davon*!", footnotes: ["viell. auch: bleib lieber dabei"] },
      { number: 22, text: "Denn der als Sklave im Herrn Berufene ist ein Freigelassener des Herrn*; ebenso ist der als Freier Berufene ein Sklave Christi*.", footnotes: ["℘ Joh 8,32.36; Phim 16", "℘ Röm 6,22; Kol 4,1"] },
      { number: 23, text: "Ihr seid um einen Preis erkauft*. Werdet nicht Sklaven von Menschen!", footnotes: ["℘ Kap. 6,20"] },
      { number: 24, text: "Worin jeder berufen worden ist, Brüder, darin soll er vor Gott bleiben." },
      { number: 25, text: "Über die Jungfrauen aber habe ich kein Gebot des Herrn; ich gebe aber eine Meinung als einer, der vom Herrn die Barmherzigkeit empfangen hat*, vertrauenswürdig zu sein*.", heading: "Über die Unverheirateten", footnotes: ["℘ 2Kor 4,1", "℘ V. 10; 1Tim 1,12"] },
      { number: 26, text: "Ich meine nun, dass dies um der gegenwärtigen* Not willen gut ist, dass es für einen Menschen gut ist, so zu sein*.", footnotes: ["viell. auch: bevorstehenden", "d. h. zu bleiben, wie er ist"] },
      { number: 27, text: "Bist du an eine Frau gebunden, so suche nicht los zu werden; bist du frei von einer Frau, so suche keine Frau!" },
      { number: 28, text: "Wenn du aber doch heiratest, so sündigst du nicht; und wenn die Jungfrau heiratet, so sündigt sie nicht; aber solche werden Bedrängnis für das Fleisch haben; ich aber möchte euch schonen*.", footnotes: ["w. ich aber schone euch"] },
      { number: 29, text: "Dies aber sage ich, Brüder: Die Zeit ist begrenzt*: dass künftig die, die Frauen haben, seien, als hätten sie keine,", footnotes: ["℘ Röm 13,11"] },
      { number: 30, text: "und die Weinenden, als weinten sie nicht, und die sich Freuenden, als freuten sie sich nicht, und die Kaufenden, als behielten sie es nicht," },
      { number: 31, text: "und die die Welt Nutzenden, als benutzten sie sie nicht*; denn die Gestalt dieser Welt vergeht*.", footnotes: ["als nutzten sie sie nicht aus; im Griech. steht hier ein stärkeres Wort als in V. 31a", "℘ Jes 51,6; 1Jo 2,17"] },
      { number: 32, text: "Ich will aber, dass ihr ohne Sorge seid*. Der Unverheiratete ist für die <Sache> des Herrn besorgt, wie er dem Herrn gefallen möge;", footnotes: ["℘ Mt 6,25"] },
      { number: 33, text: "der Verheiratete aber ist um die <Dinge> der Welt besorgt, wie er der Frau gefallen möge*,", footnotes: ["℘ Lk 14,20"] },
      { number: 34, text: "und <so> ist er geteilt. Die unverheiratete Frau und die Jungfrau ist für die <Sache> des Herrn besorgt, damit sie heilig sei an Leib und Geist; die Verheiratete aber ist für die <Sache> der Welt besorgt, wie sie dem Mann gefallen möge." },
      { number: 35, text: "Dies aber sage ich zu eurem eigenen Nutzen, nicht, um euch eine Schlinge überzuwerfen, sondern damit ihr ehrbar und beständig ohne Ablenkung beim Herrn bleibt." },
      { number: 36, text: "Wenn aber jemand denkt, er handle ungeziemend mit seiner Jungfrau, wenn er in der Vollkraft steht*, und es muss so geschehen, so tue er, was er will; er sündigt nicht; sie sollen heiraten.", footnotes: ["o. wenn sie über die Blüte hinaus ist"] },
      { number: 37, text: "Wer aber im Herzen feststeht und keine Not, sondern Macht* hat über seinen eigenen Willen und dies in seinem Herzen beschlossen hat, seine Jungfrau zu bewahren, der handelt gut.", footnotes: ["o. Vollmacht"] },
      { number: 38, text: "Also, wer seine Jungfrau heiratet*, handelt gut, und wer <sie> nicht heiratet*, wird besser handeln.", footnotes: ["o. verheiratet", "o. verheiratet"] },
      { number: 39, text: "Eine Frau ist gebunden, solange ihr Mann lebt; wenn aber der Mann entschlafen ist, so ist sie frei, sich zu verheiraten*, an wen sie will, nur im Herrn <muss es geschehen>.", footnotes: ["℘ Röm 7,1.2"] },
      { number: 40, text: "Glückseliger ist sie aber, wenn sie so bleibt, nach meiner Meinung; ich denke aber, dass auch ich Gottes Geist habe*.", footnotes: ["℘ V. 10; 1Tim 1,12"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "Was aber das Götzenopferfleisch betrifft*, so wissen wir, dass wir alle Erkenntnis haben. Die Erkenntnis bläht auf, die Liebe aber erbaut*.", heading: "Rücksicht auf die Schwachen beim Essen von Götzenopferfleisch", footnotes: ["℘ Apg 15,29", "℘ Kap. 13,4; Gal 5,13; Eph 4,16"] },
      { number: 2, text: "Wenn jemand meint, er habe etwas erkannt, so hat er noch nicht erkannt, wie man erkennen soll*;", footnotes: ["℘ Gal 6,3"] },
      { number: 3, text: "wenn aber jemand Gott liebt, der ist von ihm erkannt*.", footnotes: ["℘ Gal 4,9"] },
      { number: 4, text: "Was nun das Essen von Götzenopferfleisch betrifft, so wissen wir, dass es keinen Götzen in der Welt gibt* und dass kein Gott ist als nur einer *.", footnotes: ["℘ Kap. 10,19", "℘ 5Mo 4,35.39; Mk 12,32"] },
      { number: 5, text: "Denn wenn es auch sogenannte Götter gibt im Himmel oder auf Erden — wie es ja viele Götter und viele Herren gibt —," },
      { number: 6, text: "so ist doch für uns ein Gott*, der Vater*, von dem alle Dinge sind* und wir auf ihn hin, und ein Herr, Jesus Christus*, durch den alle Dinge sind* und wir durch ihn.", footnotes: ["℘ Kap. 12,6; Jes 45,14; Joh 17,3", "℘ Eph 4,6", "℘ Kap. 11,12; Apg 17,25; Röm 11,36", "℘ Kap. 12,5; Lk 2,11; Eph 4,5", "℘ Joh 1,3"] },
      { number: 7, text: "Die Erkenntnis aber ist nicht in allen, sondern manche essen es, da sie bis jetzt an den Götzen gewöhnt waren, als Götzenopferfleisch, und ihr Gewissen, da es schwach ist, wird befleckt*.", footnotes: ["℘ Kap. 10,28; Röm 14,23"] },
      { number: 8, text: "Speise aber macht uns nicht angenehm vor Gott; weder sind wir, wenn wir nicht essen, geringer, noch sind wir, wenn wir essen, besser*.", footnotes: ["w. überreich (d. h. an göttlicher Anerkennung)\n℘ Röm 14,17; Kol 2,16; Hebr 13,9"] },
      { number: 9, text: "Seht aber zu, dass nicht etwa diese eure Freiheit* den Schwachen zum Anstoß werde*!", footnotes: ["o. Macht, Vollmacht", "℘ Kap. 10,32; Röm 14,13; Gal 5,13"] },
      { number: 10, text: "Denn wenn jemand dich, der du Erkenntnis hast, im Götzentempel zu Tisch liegen sieht, wird nicht sein Gewissen, da er schwach ist, bestärkt* werden, die Götzenopfer zu essen?", footnotes: ["w. erbaut (vielleicht ironisch gemeint)"] },
      { number: 11, text: "Und durch deine Erkenntnis kommt der Schwache um, der Bruder, um dessentwillen Christus gestorben ist*.", footnotes: ["℘ Röm 14,15"] },
      { number: 12, text: "Wenn ihr aber so gegen die Brüder sündigt und ihr schwaches Gewissen verletzt, so sündigt ihr gegen Christus." },
      { number: 13, text: "Darum, wenn eine Speise meinem Bruder Ärgernis* gibt, so will ich nie und nimmermehr* Fleisch essen, damit ich meinem Bruder kein Ärgernis* gebe*.", footnotes: ["o. Anlass zur Sünde", "w. keinesfalls in Ewigkeit (griech. Äon)", "o. keinen Anlass zur Sünde", "℘ Kap. 9,22; Röm 14,21"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "Bin ich nicht frei*? Bin ich nicht Apostel? Habe ich nicht Jesus, unseren Herrn, gesehen*? Seid nicht ihr mein Werk im Herrn*?", heading: "Anspruch der Diener Gottes auf Unterhalt — Des Apostels Verzicht darauf", footnotes: ["℘ V. 19", "℘ Kap. 15,8; Apg 22,14.18", "℘ Kap. 4,15"] },
      { number: 2, text: "Wenn ich für andere kein Apostel bin, so bin ich es doch für euch; denn das Siegel meines Apostelamtes seid ihr im Herrn*.", footnotes: ["℘ 2Kor 3,2.3; 12,12"] },
      { number: 3, text: "Meine Verteidigung vor denen, die mich zur Untersuchung ziehen, ist diese*:", footnotes: ["℘ 2Kor 12,19"] },
      { number: 4, text: "Haben wir etwa kein Recht*, zu essen und zu trinken*?", footnotes: ["o. Macht, Vollmacht", "℘ Mt 10,10; 2Thes 3,9"] },
      { number: 5, text: "Haben wir etwa kein Recht*, eine Schwester als Frau mitzunehmen wie die übrigen Apostel und die Brüder des Herrn und Kephas*?", footnotes: ["o. Macht, Vollmacht", "griech. petros; lat. petrus\n℘ Lk 4,38; Joh 1,42"] },
      { number: 6, text: "Oder haben allein ich und Barnabas* kein Recht*, nicht zu arbeiten*?", footnotes: ["℘ Apg 4,36", "o. Macht, Vollmacht", "℘ 1Thes 2,6"] },
      { number: 7, text: "Wer tut jemals Kriegsdienste auf eigenen Sold? Wer pflanzt einen Weinberg und isst dessen Frucht nicht? Oder wer hütet eine Herde und isst nicht von der Milch der Herde*?", footnotes: ["℘ 2Tim 2,6"] },
      { number: 8, text: "Rede ich dies etwa nach Menschen<weise>, oder sagt das nicht auch das Gesetz?" },
      { number: 9, text: "Denn in dem Gesetz Moses steht geschrieben: »Du sollst dem Ochsen, der da drischt, nicht das Maul verbinden«*. Ist Gott etwa um die Ochsen besorgt?", footnotes: ["℘ 5Mo 25,4; 1Tim 5,18"] },
      { number: 10, text: "Oder spricht er <nicht> durchaus um unsertwillen? Denn es ist um unsertwillen geschrieben, dass der Pflüger auf Hoffnung pflügen und der Dreschende <dreschen> soll auf Hoffnung, <am Ertrag> teilzuhaben." },
      { number: 11, text: "Wenn wir euch das Geistliche gesät haben, was ist es da Großes, wenn wir von euch das Irdische* ernten*?", footnotes: ["w. das Fleischliche", "℘ Röm 15,27; Gal 6,6"] },
      { number: 12, text: "Wenn andere an dem Recht* über euch Anteil haben, nicht erst recht wir? Wir haben aber von diesem Recht* keinen Gebrauch gemacht, sondern wir ertragen alles*, damit wir dem Evangelium Christi kein Hindernis bereiten*.", footnotes: ["o. an der Macht, an der Vollmacht", "o. von dieser Macht, Vollmacht", "℘ Apg 18,3", "℘ 2Kor 11,7-9"] },
      { number: 13, text: "Wisst ihr nicht, dass die, welche die heiligen Dienste tun, aus dem Tempel* essen, dass die, welche am Altar tätig sind, Anteil am Altar haben*?", footnotes: ["o. <Opfergaben> von dem Heiligen", "℘ 4Mo 18,10.31; 5Mo 18,1-4"] },
      { number: 14, text: "So hat auch der Herr denen, die das Evangelium verkündigen, verordnet, vom Evangelium zu leben*.", footnotes: ["℘ Lk 10,7"] },
      { number: 15, text: "Ich aber habe von keinem dieser Dinge Gebrauch gemacht*. Ich habe dies jedoch nicht geschrieben, damit es so mit mir geschehe; denn es wäre mir besser, zu sterben, als — meinen Ruhm soll mir niemand zunichte machen*.", footnotes: ["℘ Kap. 4,12", "℘ 2Kor 11,9.10"] },
      { number: 16, text: "Denn wenn ich das Evangelium verkündige, so habe ich keinen Ruhm, denn ein Zwang liegt auf mir. Denn wehe mir, wenn ich das Evangelium nicht verkündigte*!", footnotes: ["℘ Apg 4,20; Röm 1,14"] },
      { number: 17, text: "Wenn ich dies nämlich freiwillig tue, so habe ich Lohn <zu erwarten>*, wenn aber unfreiwillig, so bin ich <nur> mit einer Verwaltung betraut.", footnotes: ["℘ 1Petr 5,2.4"] },
      { number: 18, text: "Was ist nun mein Lohn? Dass ich bei meiner Verkündigung* das Evangelium kostenfrei mache, so dass ich von meinem Recht* am Evangelium keinen Gebrauch mache.", footnotes: ["w. das Evangelium verkündigend", "o. von meiner Macht, Vollmacht"] },
      { number: 19, text: "Denn obwohl ich allen gegenüber frei bin*, habe ich mich allen zum Sklaven gemacht, damit ich so viele wie möglich* gewinne.", heading: "Der Apostel als aller Menschen Sklave und als Wettkämpfer", footnotes: ["℘ V. 1", "w. die Mehreren, o. die Mehrzahl"] },
      { number: 20, text: "Und ich bin den Juden wie ein Jude geworden*, damit ich die Juden gewinne; denen, die unter Gesetz sind, wie einer unter Gesetz — obwohl ich selbst nicht unter Gesetz bin —, damit ich die, welche unter Gesetz sind, gewinne;", footnotes: ["℘ Apg 16,3; 21,24"] },
      { number: 21, text: "denen, die ohne Gesetz sind, wie einer ohne Gesetz* — obwohl ich nicht ohne Gesetz vor Gott bin, sondern unter dem Gesetz Christi —, damit ich die, welche ohne Gesetz sind, gewinne*.", footnotes: ["o. den Gesetzlosen wie ein Gesetzloser", "℘ Gal 3,5"] },
      { number: 22, text: "Den Schwachen bin ich ein Schwacher geworden*, damit ich die Schwachen gewinne. Ich bin allen alles geworden, damit ich auf alle Weise einige rette*.", footnotes: ["℘ Kap. 8,13; Röm 15,1", "℘ Kap. 10,33; Röm 11,14"] },
      { number: 23, text: "Ich tue aber alles um des Evangeliums willen, um an ihm Anteil zu bekommen." },
      { number: 24, text: "Wisst ihr nicht, dass die, welche in der Rennbahn laufen, zwar alle laufen, aber einer den Preis empfängt? Lauft so, dass ihr ihn erlangt*!", footnotes: ["℘ Phil 3,14; Kol 2,18; Hebr 12,1"] },
      { number: 25, text: "Jeder aber, der kämpft, ist enthaltsam in allem*; jene freilich, damit sie einen vergänglichen Siegeskranz empfangen, wir aber einen unvergänglichen*.", footnotes: ["℘ 2Tim 2,4.5", "℘ 2Tim 4,8; 1Petr 5,4"] },
      { number: 26, text: "Ich laufe nun so, nicht wie ins Ungewisse; ich kämpfe so, nicht wie einer, der in die Luft schlägt;" },
      { number: 27, text: "sondern ich zerschlage meinen Leib und knechte* ihn*, damit ich nicht, nachdem ich anderen gepredigt, selbst verwerflich werde.", footnotes: ["o. versklave", "℘ Gal 5,24"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "Denn ich will nicht, dass ihr in Unkenntnis darüber seid, Brüder*, dass unsere Väter alle unter der Wolke waren* und alle durch das Meer hindurchgegangen sind*", heading: "Warnung vor sündiger Lust", footnotes: ["℘ Kap. 12,1; 2Kor 1,8; 1Thes 4,13", "℘ 2Mo 13,21", "℘ 2Mo 14,19-22"] },
      { number: 2, text: "und alle in der Wolke und im Meer auf Mose getauft wurden" },
      { number: 3, text: "und alle dieselbe geistliche Speise aßen*", footnotes: ["℘ 2Mo 16,15; 5Mo 8,3"] },
      { number: 4, text: "und alle denselben geistlichen Trank tranken*, denn sie tranken aus einem geistlichen Felsen*, der <sie> begleitete. Der Fels aber war der Christus.", footnotes: ["℘ Ps 78,15", "℘ 2Mo 17,6"] },
      { number: 5, text: "An den meisten von ihnen aber hatte Gott kein Wohlgefallen*, denn sie sind in der Wüste hingestreckt worden*.", footnotes: ["℘ Hebr 10,38", "℘ 4Mo 14,29; Ps 106,26; Joh 6,49; Hebr 3,17"] },
      { number: 6, text: "Diese Dinge aber sind als Vorbilder für uns* geschehen, damit wir nicht nach Bösem gierig sind, wie jene gierig waren*.", footnotes: ["w. von uns", "w. damit wir nicht nach bösen <Dingen> Begehrende sind, wie jene begehrten\n℘ 4Mo 11,4.34"] },
      { number: 7, text: "Werdet auch nicht Götzendiener wie einige von ihnen!, wie geschrieben steht: »Das Volk setzte sich nieder, zu essen und zu trinken, und sie standen auf, zu spielen.«*", footnotes: ["℘ 2Mo 32,6"] },
      { number: 8, text: "Auch lasst uns nicht Unzucht* treiben*, wie einige von ihnen Unzucht trieben, und es fielen an einem Tag dreiundzwanzigtausend*.", footnotes: ["o. Hurerei", "℘ Kap. 6,13.18", "℘ 4Mo 25,1.9; Ps 106,29"] },
      { number: 9, text: "Lasst uns auch den Christus* nicht versuchen*, wie einige von ihnen ihn versuchten und von den Schlangen umgebracht wurden*.", footnotes: ["mit mehreren alten Handschr.: den Herrn", "℘ Mt 4,7", "℘ 4Mo 21,5.6"] },
      { number: 10, text: "Murrt auch nicht, wie einige von ihnen murrten und von dem Verderber umgebracht wurden*!", footnotes: ["℘ 4Mo 14,2.27.37; 16,11.35; 17,6.14; Jud 16"] },
      { number: 11, text: "Alles dies aber widerfuhr jenen als Vorbild und ist geschrieben worden zur Ermahnung für uns*, über die das Ende der Zeitalter* gekommen ist*.", footnotes: ["℘ Röm 15,4", "w. die Enden der Zeitalter (griech. Äonen)", "℘ Hebr 9,26; 1Petr 4,7"] },
      { number: 12, text: "Daher, wer zu stehen meint, sehe zu, dass er nicht falle*.", footnotes: ["℘ Röm 11,20; Gal 6,1"] },
      { number: 13, text: "Keine Versuchung hat euch ergriffen als nur eine menschliche; Gott aber ist treu*, der nicht zulassen wird, dass ihr über euer Vermögen versucht werdet, sondern mit der Versuchung auch den Ausgang schaffen wird, so dass* ihr sie ertragen könnt*.", footnotes: ["℘ Kap. 1,9", "o. damit", "℘ 2Petr 2,9"] },
      { number: 14, text: "Darum, meine Geliebten, flieht den Götzendienst*!", heading: "Warnung vor Götzendienst im Blick auf den Tisch des Herrn", footnotes: ["℘ 1Jo 5,21"] },
      { number: 15, text: "Ich rede als zu Verständigen*. Beurteilt ihr, was ich sage*!", footnotes: ["o. Einsichtsvollen, o. Urteilsfähigen", "℘ Kap. 11,13"] },
      { number: 16, text: "Der Kelch des Segens, den wir segnen*, ist er nicht <die> Gemeinschaft des Blutes des Christus? Das Brot, das wir brechen*, ist es nicht <die> Gemeinschaft des Leibes des Christus*?", footnotes: ["o. den wir preisen, o. für den wir danken", "℘ Apg 2,42", "℘ Kap. 11,23-25"] },
      { number: 17, text: "Denn ein Brot, ein Leib sind wir, die vielen*, denn wir alle nehmen teil an dem einen Brot.", footnotes: ["℘ Kap. 12,12.27; Eph 4,4"] },
      { number: 18, text: "Seht auf das Israel nach dem Fleisch! Sind nicht die, welche die Schlachtopfer essen*, in Gemeinschaft mit dem Altar*?", footnotes: ["℘ 3Mo 7,6.15", "w. Teilhaber des Altars"] },
      { number: 19, text: "Was sage ich nun? Dass das einem Götzen Geopferte etwas sei? Oder dass ein Götzenbild etwas sei*?", footnotes: ["℘ Kap. 8,4"] },
      { number: 20, text: "<Nein,> sondern dass das, was sie* opfern, sie den Dämonen opfern* und nicht Gott. Ich will aber nicht, dass ihr Gemeinschaft habt mit den* Dämonen*.", footnotes: ["d. h. die Nationen; mehrere Handschr. fügen für »sie« »die Nationen« ein", "℘ Ps 106,37", "w. dass ihr Teilhaber seid der", "℘ Offb 2,20"] },
      { number: 21, text: "Ihr könnt nicht des Herrn Kelch trinken und der Dämonen Kelch; ihr könnt nicht am Tisch des Herrn* teilnehmen und am Tisch der Dämonen*.", footnotes: ["℘ Mal 1,7.12", "℘ Apg 15,20; 2Kor 6,15.16"] },
      { number: 22, text: "Oder wollen wir den Herrn zur Eifersucht reizen*? Sind wir etwa stärker als er?", footnotes: ["℘ 5Mo 32,21; Ps 78,58\nw. reizen wir den Herrn zur Eifersucht"] },
      { number: 23, text: "Alles ist erlaubt, aber nicht alles ist nützlich*; alles ist erlaubt, aber nicht alles erbaut.", heading: "Mahnung zum rechten Gebrauch der Freiheit beim Essen des Götzenopferfleisches", footnotes: ["℘ Kap. 6,12"] },
      { number: 24, text: "Niemand suche das Seine, sondern das des anderen*.", footnotes: ["℘ V. 33; Kap. 13,5; Röm 15,1.2; Phil 2,4.21"] },
      { number: 25, text: "Alles, was auf dem Fleischmarkt verkauft wird, esst, ohne es um des Gewissens willen zu untersuchen*!", footnotes: ["℘ 1Tim 4,4"] },
      { number: 26, text: "Denn »die Erde ist des Herrn und ihre Fülle*«.", footnotes: ["℘ Ps 24,1; 50,12"] },
      { number: 27, text: "Wenn jemand von den Ungläubigen euch einlädt, und ihr wollt hingehen, so esst alles, was euch vorgesetzt wird, ohne es um des Gewissens willen zu untersuchen." },
      { number: 28, text: "Wenn aber jemand zu euch sagt: Dies ist Opferfleisch, so esst nicht, um jenes willen, der es anzeigt, und um des Gewissens willen*!", footnotes: ["℘ Kap. 8,7"] },
      { number: 29, text: "Ich meine aber nicht das eigene Gewissen, sondern das des anderen*. Denn warum wird meine Freiheit von einem anderen Gewissen beurteilt?", footnotes: ["℘ Röm 14,15"] },
      { number: 30, text: "Wenn ich mit Danksagung teilnehme, warum werde ich geschmäht für das, wofür ich danksage*?", footnotes: ["℘ 1Tim 4,4"] },
      { number: 31, text: "Ob ihr nun esst oder trinkt oder sonst etwas tut, tut alles zur Ehre Gottes*!", footnotes: ["℘ Kap. 6,20; Röm 14,6; Kol 3,17; 1Petr 4,11"] },
      { number: 32, text: "Seid unanstößig, sowohl für Juden als auch für Griechen* als auch für die Gemeinde* Gottes*!", footnotes: ["s. Anm. zu Kap. 1,22", "o. Versammlung", "℘ Kap. 8,9; 2Kor 8,21"] },
      { number: 33, text: "wie auch ich in allen Dingen allen zu gefallen strebe, dadurch, dass ich nicht meinen Vorteil suche, sondern den der vielen, dass sie gerettet werden*.", footnotes: ["℘ V. 24; Kap. 9,19-22"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "Seid meine Nachahmer*, wie auch ich Christi <Nachahmer bin>!", footnotes: ["℘ Kap. 4,16"] },
      { number: 2, text: "Ich lobe euch aber, dass ihr in allem meiner gedenkt und die Überlieferungen*, wie ich sie euch überliefert habe, festhaltet*.", heading: "Mahnung zum rechten Verhalten beim Gebet", footnotes: ["o. Unterweisungen", "℘ 1Thes 4,1.2; 2Thes 2,15"] },
      { number: 3, text: "Ich will aber, dass ihr wisst, dass der Christus das Haupt eines jeden Mannes ist, das Haupt der Frau aber der Mann*, des Christus Haupt aber Gott*.", footnotes: ["℘ Kap. 14,34; 1Mo 3,16; Eph 5,23", "℘ Kap. 3,23; 15,28"] },
      { number: 4, text: "Jeder Mann, der betet oder weissagt und <dabei etwas> auf dem Haupt hat, entehrt sein Haupt." },
      { number: 5, text: "Jede Frau aber, die mit unverhülltem Haupt betet oder weissagt*, entehrt ihr Haupt; denn sie ist ein und dasselbe wie die Geschorene.", footnotes: ["℘ Apg 2,17; 21,9"] },
      { number: 6, text: "Denn wenn eine Frau sich nicht verhüllt, so werde <ihr> auch <das Haar> abgeschnitten; wenn es aber für eine Frau schändlich ist*, dass <ihr das Haar> abgeschnitten oder geschoren wird, so soll sie sich verhüllen.", footnotes: ["℘ Kap. 14,35"] },
      { number: 7, text: "Denn der Mann freilich soll sich das Haupt nicht verhüllen, da er Gottes Bild und Abglanz* ist*; die Frau aber ist des Mannes Abglanz*.", footnotes: ["o. Herrlichkeit", "℘ 1Mo 1,27; 5,1", "o. Herrlichkeit"] },
      { number: 8, text: "Denn der Mann ist nicht von der Frau, sondern die Frau vom Mann*;", footnotes: ["℘ 1Mo 2,22.23; 1Tim 2,13"] },
      { number: 9, text: "denn der Mann wurde auch nicht um der Frau willen geschaffen, sondern die Frau um des Mannes willen*.", footnotes: ["℘ 1Mo 2,18"] },
      { number: 10, text: "Darum soll die Frau eine Macht* auf dem Haupt haben um der Engel willen*.", footnotes: ["d. h. ein Zeichen der Macht, unter der sie steht", "℘ 1Tim 5,21"] },
      { number: 11, text: "Dennoch ist im Herrn weder die Frau ohne den Mann, noch der Mann ohne die Frau." },
      { number: 12, text: "Denn wie die Frau vom Mann ist, so ist auch der Mann durch die Frau; alles aber von Gott*.", footnotes: ["℘ Kap. 8,6"] },
      { number: 13, text: "Urteilt bei euch selbst*: Ist es anständig, dass eine Frau unverhüllt zu Gott betet?", footnotes: ["℘ Kap. 10,15"] },
      { number: 14, text: "Und lehrt euch nicht selbst die Natur, dass, wenn ein Mann langes Haar hat, es eine Schande für ihn ist," },
      { number: 15, text: "wenn aber eine Frau langes Haar hat, es eine Ehre für sie ist? Denn das Haar ist ihr anstatt eines Schleiers gegeben." },
      { number: 16, text: "Wenn es aber jemand für gut hält, streitsüchtig zu sein, <so soll er wissen:> wir haben eine derartige Gewohnheit nicht, auch nicht die Gemeinden* Gottes.", footnotes: ["o. Versammlungen"] },
      { number: 17, text: "Wenn ich aber Folgendes vorschreibe, so lobe ich nicht*, dass ihr nicht zum Besseren, sondern zum Schlechteren zusammenkommt*.", heading: "Mahnung zum rechten Verhalten beim Herrenmahl", footnotes: ["vgl. V. 2", "℘ V. 22"] },
      { number: 18, text: "Denn erstens höre ich, dass, wenn ihr in der Gemeinde* zusammenkommt, Spaltungen unter euch sind, und zum Teil glaube ich es*.", footnotes: ["o. Versammlung", "℘ Kap. 1,11"] },
      { number: 19, text: "Denn es müssen auch Parteiungen unter euch sein, damit die Bewährten unter euch offenbar werden." },
      { number: 20, text: "Wenn ihr nun zusammenkommt*, so ist es nicht <möglich>, das Herrenmahl* zu essen*.", footnotes: ["℘ Kap. 14,26", "w. das dem Herrn gehörende Mahl", "o. so ist das nicht das Herrenmahl essen"] },
      { number: 21, text: "Denn jeder nimmt beim Essen sein eigenes Mahl* vorweg, und der eine ist hungrig, der andere ist betrunken.", footnotes: ["o. Abendessen"] },
      { number: 22, text: "Habt ihr denn nicht Häuser, um zu essen und zu trinken? Oder verachtet ihr die Gemeinde* Gottes und beschämt die, welche nichts haben*? Was soll ich euch sagen? Soll ich euch loben? Hierin lobe ich nicht*.", footnotes: ["o. Versammlung", "℘ Jak 2,6", "℘ V. 17"] },
      { number: 23, text: "Denn ich habe von dem Herrn empfangen, was ich auch euch überliefert habe*, dass der Herr Jesus in der Nacht, in der er überliefert wurde, Brot nahm", footnotes: ["℘ Kap. 15,3; Gal 1,12"] },
      { number: 24, text: "und, als er gedankt hatte, es brach und sprach: Dies ist mein Leib, der für euch ist; dies tut zu meinem Gedächtnis*!", footnotes: ["℘ Ps 111,4"] },
      { number: 25, text: "Ebenso auch den Kelch nach dem Mahl* und sprach: Dieser Kelch ist der neue Bund in meinem Blut*, dies tut, sooft ihr trinkt, zu meinem Gedächtnis*!", footnotes: ["w. nach dem Essen (Infinitiv)", "℘ Kap. 10,16", "℘ Mt 26,26-28; Mk 14,22-24; Lk 22,19.20"] },
      { number: 26, text: "Denn sooft ihr dieses Brot esst und den Kelch trinkt, verkündigt ihr den Tod des Herrn, bis er kommt*.", footnotes: ["℘ 1Thes 4,16"] },
      { number: 27, text: "Wer also unwürdig* das Brot isst oder den Kelch des Herrn trinkt, wird des* Leibes und Blutes des Herrn schuldig sein.", footnotes: ["d. h. in unwürdiger Weise (Adverb)", "o. an dem"] },
      { number: 28, text: "Der Mensch aber prüfe sich selbst*, und so esse er von dem Brot und trinke von dem Kelch.", footnotes: ["℘ 2Kor 13,5"] },
      { number: 29, text: "Denn wer isst und trinkt, isst und trinkt sich selbst Gericht, wenn er den Leib <des Herrn> nicht <richtig> beurteilt*.", footnotes: ["o. nicht unterscheidet"] },
      { number: 30, text: "Deshalb sind viele unter euch schwach und krank, und ein gut Teil sind entschlafen." },
      { number: 31, text: "Wenn wir uns aber selbst beurteilten*, so würden wir nicht gerichtet.", footnotes: ["o. unterschieden"] },
      { number: 32, text: "Wenn wir aber vom Herrn gerichtet werden, so werden wir gezüchtigt, damit wir nicht mit der Welt verurteilt werden*.", footnotes: ["℘ Hebr 12,10; 1Petr 4,17"] },
      { number: 33, text: "Daher, meine Brüder, wenn ihr zusammenkommt, um zu essen, so wartet aufeinander!" },
      { number: 34, text: "Wenn jemand hungert, der esse daheim, damit ihr nicht zum Gericht zusammenkommt. Das Übrige aber will ich anordnen, sobald ich komme." },
    ]},
    { number: 12, verses: [
      { number: 1, text: "Was aber die geistlichen <Gaben> betrifft, Brüder, so will ich nicht, dass ihr ohne Kenntnis seid*.", heading: "Die verschiedenen Geistesgaben und die Einheit des Leibes und seiner Glieder", footnotes: ["℘ Kap. 10,1"] },
      { number: 2, text: "Ihr wisst, dass ihr, als ihr zu den Heiden* gehörtet, zu den stummen Götzenbildern hingezogen, ja, fortgerissen wurdet*.", footnotes: ["griech. ethne; sonst gewöhnlich mit »Nationen« übersetzt", "℘ Gal 4,8; 1Thes 1,9"] },
      { number: 3, text: "Deshalb tue ich euch kund, dass niemand, der im Geist Gottes redet, sagt: Fluch* über Jesus!, und niemand sagen kann: Herr Jesus!*, außer im* Heiligen Geist.", footnotes: ["o. Herr ist Jesus!", "o. Herr ist Jesus!", "d. h. in der Kraft des; so auch V. 9.13"] },
      { number: 4, text: "Es gibt aber Verschiedenheiten von Gnadengaben*, aber <es ist> derselbe Geist*;", footnotes: ["griech. charisma; d. h. einfach »Gabe« oder »Geschenk«; im NT ist meist eine Gabe Gottes bzw. des Geistes gemeint\n℘ Röm 12,6-8; Eph 4,7.11", "℘ Eph 4,4"] },
      { number: 5, text: "und es gibt Verschiedenheiten von Diensten*, und <es ist> derselbe Herr;", footnotes: ["℘ V. 28"] },
      { number: 6, text: "und es gibt Verschiedenheiten von Wirkungen, aber <es ist> derselbe Gott*, der alles in allen wirkt*.", footnotes: ["℘ Kap. 8,5.6", "℘ Eph 4,6"] },
      { number: 7, text: "Jedem aber wird die Offenbarung des Geistes zum Nutzen gegeben*.", footnotes: ["℘ Kap. 14,26; Eph 4,12; 1Petr 4,10"] },
      { number: 8, text: "Denn dem einen wird durch den Geist das Wort der Weisheit gegeben*; einem anderen aber das Wort der Erkenntnis* nach demselben Geist;", footnotes: ["℘ Kap. 2,7", "℘ Kap. 1,5; 13,2"] },
      { number: 9, text: "einem anderen aber Glauben* in demselben Geist; einem anderen aber Gnadengaben* der Heilungen* in dem einen Geist;", footnotes: ["℘ Jak 5,15", "griech. charisma; d. h. einfach »Gabe« oder »Geschenk«; im NT ist meist eine Gabe Gottes bzw. des Geistes gemeint", "℘ Apg 19,11.12; Gal 3,5"] },
      { number: 10, text: "einem anderen aber Wunderwirkungen*; einem anderen aber Weissagung*, einem anderen aber Unterscheidungen der Geister*; einem anderen <verschiedene> Arten von Sprachen*; einem anderen aber Auslegung der Sprachen*.", footnotes: ["o. Machtwirkungen\n℘ Apg 19,11.12; Gal 3,5", "o. Prophetengabe\n℘ Kap. 14,1.3", "℘ 1Jo 4,1", "o. Zungen\n℘ Apg 2,4", "o. Zungen\n℘ Kap. 14,5.13.27"] },
      { number: 11, text: "Dies alles aber wirkt ein und derselbe Geist und teilt jedem besonders aus, wie er will*.", footnotes: ["℘ Kap. 7,7; Röm 12,3; Hebr 2,4"] },
      { number: 12, text: "Denn wie der Leib einer ist und viele Glieder hat, alle Glieder des Leibes aber, obwohl viele, ein Leib sind: so auch der Christus*.", footnotes: ["℘ V. 27; Kap. 10,17; Röm 12,4"] },
      { number: 13, text: "Denn in einem Geist sind wir alle zu einem Leib getauft worden*, es seien Juden oder Griechen*, es seien Sklaven oder Freie*, und sind alle mit einem Geist getränkt worden.", footnotes: ["℘ Apg 1,5; Eph 4,4.5", "s. Anm. zu Kap. 1,22", "℘ Gal 3,28"] },
      { number: 14, text: "Denn auch der Leib ist nicht ein Glied, sondern viele*.", footnotes: ["℘ Röm 12,4"] },
      { number: 15, text: "Wenn der Fuß spräche: Weil ich nicht Hand bin, gehöre ich nicht zum Leib; gehört er deswegen nicht zum Leib?" },
      { number: 16, text: "Und wenn das Ohr spräche: Weil ich nicht Auge bin, gehöre ich nicht zum Leib; gehört es deswegen nicht zum Leib?" },
      { number: 17, text: "Wenn der ganze Leib Auge wäre, wo wäre das Gehör? Wenn ganz Gehör, wo der Geruch?" },
      { number: 18, text: "Nun aber hat Gott die Glieder bestimmt, jedes einzelne von ihnen am Leib*, wie er wollte*.", footnotes: ["℘ Kap. 7,7; Röm 12,3; Hebr 2,4", "℘ Kap. 7,7; Röm 12,3; Hebr 2,4"] },
      { number: 19, text: "Wenn aber alles ein Glied wäre, wo wäre der Leib?" },
      { number: 20, text: "Nun aber sind zwar viele Glieder, aber ein Leib." },
      { number: 21, text: "Das Auge kann nicht zur Hand sagen: Ich brauche dich nicht; oder wieder das Haupt zu den Füßen: Ich brauche euch nicht." },
      { number: 22, text: "Sondern gerade die Glieder des Leibes, die schwächer zu sein scheinen, sind notwendig;" },
      { number: 23, text: "und die uns die weniger ehrbaren am Leib zu sein scheinen, die umgeben wir mit größerer Ehre; und unsere nichtanständigen haben größere Anständigkeit;" },
      { number: 24, text: "unsere anständigen aber brauchen es nicht. Aber Gott hat den Leib zusammengefügt und dabei dem Mangelhafteren größere Ehre gegeben," },
      { number: 25, text: "damit keine Spaltung im Leib sei*, sondern die Glieder dieselbe Sorge füreinander hätten*.", footnotes: ["℘ Kap. 1,10; Eph 4,3", "℘ Eph 4,16"] },
      { number: 26, text: "Und wenn ein Glied leidet, so leiden alle Glieder mit; oder wenn ein Glied verherrlicht wird, so freuen sich alle Glieder mit*.", footnotes: ["℘ Röm 12,15"] },
      { number: 27, text: "Ihr aber seid Christi Leib* und, einzeln genommen, Glieder*.", footnotes: ["℘ Eph 1,23", "℘ Kap. 6,15; Röm 12,5; Eph 5,30"] },
      { number: 28, text: "Und die einen hat Gott in der Gemeinde* eingesetzt erstens als Apostel*, zweitens <andere> als Propheten, drittens als Lehrer*, sodann <Wunder>kräfte, sodann Gnadengaben* der Heilungen, Hilfeleistungen*, Leitungen*, Arten von Sprachen*.", footnotes: ["o. Versammlung", "d. h. zu Gesandten, o. Boten", "℘ Apg 13,1; Eph 4,11", "griech. charisma; d. h. einfach »Gabe« oder »Geschenk«; im NT ist meist eine Gabe Gottes bzw. des Geistes gemeint", "℘ Röm 12,8", "℘ Kap. 6,15; Röm 12,5; Eph 5,30", "o. Zungen"] },
      { number: 29, text: "Sind etwa alle Apostel? Alle Propheten? Alle Lehrer? Haben alle <Wunder>kräfte?" },
      { number: 30, text: "Haben alle Gnadengaben* der Heilungen? Reden alle in Sprachen? Legen alle aus?", footnotes: ["griech. charisma; d. h. einfach »Gabe« oder »Geschenk«; im NT ist meist eine Gabe Gottes bzw. des Geistes gemeint"] },
      { number: 31, text: "Eifert aber um die größeren Gnadengaben*! Und einen Weg noch weit darüber hinaus zeige ich euch:", footnotes: ["griech. charisma; d. h. einfach »Gabe« oder »Geschenk«; im NT ist meist eine Gabe Gottes bzw. des Geistes gemeint\n℘ Kap. 14,1.39"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "Wenn ich in den Sprachen* der Menschen und der Engel rede, aber keine Liebe habe, so bin ich ein tönendes Erz geworden oder eine schallende Zimbel.", heading: "Das Hohelied der Liebe", footnotes: ["o. Zungen"] },
      { number: 2, text: "Und wenn ich Weissagung* habe und alle Geheimnisse und alle Erkenntnis weiß, und wenn ich allen Glauben habe, so dass ich Berge versetze*, aber keine Liebe habe, so bin ich nichts*.", footnotes: ["o. Prophetengabe", "℘ Mt 17,20", "℘ Gal 5,6"] },
      { number: 3, text: "Und wenn ich alle meine Habe zur Speisung <der Armen> austeile und wenn ich meinen Leib hingebe, damit ich Ruhm gewinne*, aber keine Liebe habe, so nützt es mir nichts.", footnotes: ["mit anderen Handschr.: verbrannt werde"] },
      { number: 4, text: "Die Liebe ist langmütig, die Liebe ist gütig, sie neidet nicht*, die Liebe tut nicht groß*, sie bläht sich nicht auf*,", footnotes: ["o. ist nicht eifersüchtig", "℘ Jak 4,16", "℘ Kap. 8,1"] },
      { number: 5, text: "sie benimmt sich nicht unanständig, sie sucht nicht das Ihre*, sie lässt sich nicht erbittern, sie rechnet Böses nicht zu*,", footnotes: ["℘ Kap. 10,24", "o. denkt nichts Böses\n℘ Röm 13,10"] },
      { number: 6, text: "sie freut sich nicht über die Ungerechtigkeit; sondern sie freut sich mit der Wahrheit," },
      { number: 7, text: "sie erträgt alles*, sie glaubt alles, sie hofft alles, sie erduldet alles.", footnotes: ["o. deckt alles zu"] },
      { number: 8, text: "Die Liebe vergeht niemals; seien es aber Weissagungen*, sie werden weggetan werden; seien es Sprachen*, sie werden aufhören; sei es Erkenntnis, sie wird weggetan werden.", footnotes: ["o. Prophetengaben", "o. Zungen"] },
      { number: 9, text: "Denn wir erkennen stückweise, und wir weissagen* stückweise;", footnotes: ["o. prophezeien; wie Kap. 14,1—5"] },
      { number: 10, text: "wenn aber das Vollkommene kommt, wird das, was stückweise ist, weggetan werden." },
      { number: 11, text: "Als ich ein Kind war, redete ich wie ein Kind, dachte wie ein Kind, urteilte wie ein Kind; als ich ein Mann wurde, tat ich weg, was kindlich war." },
      { number: 12, text: "Denn wir sehen jetzt mittels eines Spiegels* undeutlich*, dann aber von Angesicht zu Angesicht*. Jetzt erkenne ich stückweise, dann aber werde ich erkennen*, wie auch ich erkannt* worden bin.", footnotes: ["Der Spiegel des Altertums bestand aus einer blanken Metallscheibe und gab nur ein undeutliches Bild wieder.", "o. im Rätsel", "℘ Offb 22,4", "o. vollständig o. genau erkennen (ein stärkeres Wort als vorher)", "o. vollständig o. genau erkennen (ein stärkeres Wort als vorher)"] },
      { number: 13, text: "Nun aber bleibt Glaube, Hoffnung, Liebe, diese drei; die Größte* aber von diesen ist die Liebe.", footnotes: ["w. größer"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "Strebt nach der Liebe*; eifert aber nach den geistlichen <Gaben>, besonders aber, dass ihr weissagt*!", heading: "Über das Reden und Beten in Sprachen", footnotes: ["℘ Eph 5,2", "℘ Kap. 12,31"] },
      { number: 2, text: "Denn wer in einer Sprache* redet, redet nicht zu Menschen, sondern zu Gott*; denn niemand versteht* es, im Geist aber redet er Geheimnisse.", footnotes: ["o. in einer Zunge", "℘ Apg 10,46", "w. hört"] },
      { number: 3, text: "Wer aber weissagt, redet zu den Menschen <zur> Erbauung* und Ermahnung* und Tröstung.", footnotes: ["o. <zum> Aufbau", "o. Ermunterung"] },
      { number: 4, text: "Wer in einer Sprache* redet, erbaut sich selbst; wer aber weissagt, erbaut die Gemeinde*.", footnotes: ["o. in einer Zunge", "o. Versammlung; so auch V. 5—23"] },
      { number: 5, text: "Ich möchte aber, dass ihr alle in Sprachen* redet*, mehr aber <noch>, dass ihr weissagt. Wer aber weissagt, ist größer, als wer in Sprachen* redet, es sei denn, dass er es auslegt*, damit die Gemeinde Erbauung* empfange.", footnotes: ["o. in Zungen", "℘ 4Mo 11,29", "o. in Zungen", "℘ Kap. 12,10", "o. Aufbau"] },
      { number: 6, text: "Jetzt aber, Brüder, wenn ich zu euch komme und in Sprachen* rede, was werde ich euch nützen, wenn ich nicht zu euch rede in Offenbarung oder in Erkenntnis oder in Weissagung oder in Lehre?", footnotes: ["o. in Zungen"] },
      { number: 7, text: "Doch auch die tönenden leblosen Dinge, Flöte oder Harfe, wenn sie den Tönen keinen Unterschied geben, wie wird man erkennen, was geflötet oder geharft wird?" },
      { number: 8, text: "Denn auch wenn die Posaune einen undeutlichen Ton gibt, wer wird sich zum Kampf rüsten?" },
      { number: 9, text: "So auch ihr, wenn ihr durch die Sprache* nicht eine verständliche Rede gebt, wie soll man erkennen, was geredet wird? Denn ihr werdet in den Wind reden.", footnotes: ["o. durch die Zunge; o. durch die Zunge<nrede>"] },
      { number: 10, text: "Es gibt zum Beispiel so viele Arten von Sprachen* in der Welt, und nichts ist ohne Sprache.", footnotes: ["w. Stimmen; in V. 10.11 ist ein anderes griech. Wort verwendet als an den übrigen Stellen"] },
      { number: 11, text: "Wenn ich nun die Bedeutung* der Sprache nicht kenne, so werde ich dem Redenden ein Barbar* sein und der Redende für mich ein Barbar.", footnotes: ["w. Kraft", "So wurden von den Griechen und Römern alle Völker genannt, die nicht griech. oder röm. Abstammung waren und eine fremde Sprache redeten."] },
      { number: 12, text: "So auch ihr, da ihr nach geistlichen Gaben* eifert, so strebt danach, dass ihr überreich seid zur Erbauung* der Gemeinde*.", footnotes: ["w. um Geister", "o. zum Aufbau", "℘ V. 26; Röm 14,19"] },
      { number: 13, text: "Darum, wer in einer Sprache* redet, bete, dass er <es auch> auslege*!", footnotes: ["o. in einer Zunge", "℘ Kap. 12,10"] },
      { number: 14, text: "Denn wenn ich in einer Sprache* bete, so betet mein Geist, aber mein Verstand ist fruchtleer.", footnotes: ["o. in einer Zunge"] },
      { number: 15, text: "Was ist nun? Ich will beten mit dem Geist, aber ich will auch beten mit dem Verstand; ich will lobsingen mit dem Geist, aber ich will auch lobsingen mit dem Verstand." },
      { number: 16, text: "Denn wenn du mit dem Geist preist, wie soll der, welcher die Stelle des Unkundigen einnimmt, das Amen* sprechen* zu deiner Danksagung, da er ja nicht weiß, was du sagst?", footnotes: ["Beteuerungs- und Bekräftigungsformel; s. auch Anm. zu Röm 1,25", "℘ 1Chr 16,36; Neh 8,6"] },
      { number: 17, text: "Denn du sagst wohl gut Dank, aber der andere wird nicht erbaut." },
      { number: 18, text: "Ich danke Gott, ich rede mehr in Sprachen* als ihr alle.", footnotes: ["o. Zunge(n)"] },
      { number: 19, text: "Aber in der Gemeinde will ich <lieber> fünf Worte mit meinem Verstand reden, damit ich auch andere unterweise, als zehntausend Worte in einer Sprache*.", footnotes: ["o. Zunge(n)"] },
      { number: 20, text: "Brüder, seid nicht Kinder am Verstand, sondern an der Bosheit seid Unmündige*, am Verstand aber seid Erwachsene*!", footnotes: ["℘ Kap. 3,1", "w. Vollkommene; im Griech. ein Ausdruck für »Erwachsene«\n℘ Röm 16,19; Eph 4,13"] },
      { number: 21, text: "Es steht im Gesetz geschrieben: »Ich will durch Leute mit fremder Sprache und durch Lippen Fremder zu diesem Volk reden, und auch so werden sie nicht auf mich hören, spricht der Herr.«*", footnotes: ["℘ Jes 28,11.12"] },
      { number: 22, text: "Daher sind die Sprachen* zu einem Zeichen, nicht für die Glaubenden, sondern für die Ungläubigen*; die Weissagung aber nicht für die Ungläubigen, sondern für die Glaubenden.", footnotes: ["o. Zunge(n)", "℘ Apg 2,6-12"] },
      { number: 23, text: "Wenn nun die ganze Gemeinde zusammenkommt und alle in Sprachen* reden, und es kommen Unkundige oder Ungläubige herein, werden sie nicht sagen, dass ihr von Sinnen seid*?", footnotes: ["o. Zunge(n)", "℘ Apg 2,13"] },
      { number: 24, text: "Wenn aber alle weissagen und irgendein Ungläubiger oder Unkundiger kommt herein, so wird er von allen überführt, von allen beurteilt;" },
      { number: 25, text: "das Verborgene seines Herzens wird offenbar*, und so wird er auf sein Angesicht fallen und wird Gott anbeten und verkündigen, dass Gott wirklich unter euch ist.", footnotes: ["℘ Hebr 4,12"] },
      { number: 26, text: "Was ist nun, Brüder? Wenn ihr zusammenkommt*, so hat jeder einen Psalm, hat eine Lehre, hat eine Offenbarung, hat eine Sprache<nrede>*, hat eine Auslegung; alles geschehe zur Erbauung*.", heading: "Ordnung bei den Gemeindezusammenkünften", footnotes: ["℘ Kap. 11,18.20", "o. eine Zunge<nrede>\n℘ Kap. 12,8-10", "o. zum Aufbau\n℘ V. 12; Kap. 12,7"] },
      { number: 27, text: "Wenn nun jemand in einer Sprache* redet, <so sei es> zu zweien oder höchstens zu dritt und nacheinander, und einer lege aus.", footnotes: ["o. Zunge(n)"] },
      { number: 28, text: "Wenn aber kein Ausleger da ist, so schweige er in der Gemeinde*, rede aber für sich und für Gott.", footnotes: ["o. Versammlung; so auch V. 33—35"] },
      { number: 29, text: "<Von den> Propheten aber sollen zwei oder drei reden, und die anderen sollen urteilen*.", footnotes: ["o. unterscheiden\n℘ 1Thes 5,21"] },
      { number: 30, text: "Wenn aber einem anderen, der dasitzt, eine Offenbarung <zuteil> wird, so schweige der Erste." },
      { number: 31, text: "Denn ihr könnt einer nach dem anderen alle weissagen, damit alle lernen und alle getröstet* werden.", footnotes: ["o. ermahnt"] },
      { number: 32, text: "Und die Geister der Propheten* sind den Propheten untertan.", footnotes: ["℘ Offb 22,6"] },
      { number: 33, text: "Denn Gott ist nicht <ein Gott> der Unordnung, sondern des Friedens*. Wie <es> in allen Gemeinden der Heiligen <ist>,", footnotes: ["℘ Röm 15,33"] },
      { number: 34, text: "sollen die Frauen* in den Gemeinden* schweigen, denn es wird ihnen nicht erlaubt, zu reden, sondern sie sollen sich unterordnen*, wie auch das Gesetz sagt*.", footnotes: ["mit anderen Handschr.: eure Frauen", "o. Versammlungen", "℘ Kap. 11,3; Eph 5,22.24; Kol 3,18; 1Tim 2,11.12; Tit 2,5; 1Petr 3,1.5", "℘ 1Mo 3,16"] },
      { number: 35, text: "Wenn sie aber etwas lernen wollen, so sollen sie daheim ihre eigenen Männer fragen; denn es ist schändlich für eine Frau*, in der Gemeinde zu reden.", footnotes: ["℘ Kap. 11,6"] },
      { number: 36, text: "Oder ist das Wort Gottes von euch ausgegangen*? Oder ist es zu euch allein gelangt?", footnotes: ["℘ Jes 2,3"] },
      { number: 37, text: "Wenn jemand meint, ein Prophet oder <sonst> ein Geistbegabter* zu sein, so erkenne er, dass das, was ich euch schreibe, ein Gebot des Herrn ist.", footnotes: ["w. geistlich, o. ein geistlicher <Christ>"] },
      { number: 38, text: "Wenn aber jemand das nicht erkennt, so wird er auch <von Gott> nicht erkannt*.", footnotes: ["Andere Handschr. lesen: so sei er unwissend"] },
      { number: 39, text: "Daher, Brüder, eifert danach, zu weissagen, und hindert das Reden in Sprachen* nicht*!", footnotes: ["o. Zunge(n)", "℘ Apg 19,6"] },
      { number: 40, text: "Alles aber geschehe anständig und in Ordnung*.", footnotes: ["℘ Kap. 16,14; Kol 2,5"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "Ich tue euch aber, Brüder, das Evangelium kund, das ich euch verkündigt* habe*, das ihr auch angenommen habt, in dem ihr auch steht,", heading: "Die Auferstehungshoffnung und die Zeugen der Auferstehung Christi", footnotes: ["o. als Evangelium verkündigt", "℘ Gal 1,11"] },
      { number: 2, text: "durch das ihr auch gerettet werdet*, wenn ihr festhaltet, mit welcher Rede* ich es euch verkündigt* habe*, es sei denn, dass ihr vergeblich* zum Glauben gekommen seid.", footnotes: ["℘ Kap. 1,21", "w. mit welchem Wort<laut>", "o. als Evangelium verkündigt", "℘ Kol 1,23", "℘ 2Kor 6,1"] },
      { number: 3, text: "Denn ich habe euch vor allem überliefert, was ich auch empfangen habe*: dass Christus für unsere Sünden gestorben ist* nach den Schriften*;", footnotes: ["℘ Kap. 11,23", "℘ Röm 4,25; 2Kor 5,15", "℘ Jes 53,5.6; Lk 22,22 ⇨Esyn: Synopse Nr. 361"] },
      { number: 4, text: "und dass er begraben wurde* und dass er auferweckt worden ist am dritten Tag nach den Schriften*;", footnotes: ["℘ Jes 53,9", "℘ Ps 16,10; Mt 12,40; Lk 24,46"] },
      { number: 5, text: "und dass er Kephas* erschienen ist*, dann den Zwölfen*.", footnotes: ["griech. petros; lat. petrus", "℘ Lk 24,34", "℘ Mk 16,14; Apg 1,3"] },
      { number: 6, text: "Danach erschien er mehr als fünfhundert Brüdern auf einmal, von denen die meisten bis jetzt übrig geblieben, einige aber auch entschlafen sind." },
      { number: 7, text: "Danach erschien er Jakobus, dann den Aposteln* allen*;", footnotes: ["d. h. Gesandten, o. Boten", "℘ Lk 24,50"] },
      { number: 8, text: "zuletzt aber von allen, gleichsam der unzeitigen Geburt, erschien er auch mir*.", footnotes: ["℘ Kap. 9,1"] },
      { number: 9, text: "Denn ich bin der geringste der Apostel*, der ich nicht würdig* bin, ein Apostel genannt zu werden, weil ich die Gemeinde* Gottes verfolgt habe*.", footnotes: ["℘ 1Tim 1,15", "o. tüchtig, tauglich", "o. Versammlung", "℘ Apg 8,3"] },
      { number: 10, text: "Aber durch Gottes Gnade bin ich, was ich bin*; und seine Gnade mir gegenüber ist nicht vergeblich gewesen, sondern ich habe viel mehr gearbeitet als sie alle*; nicht aber ich, sondern die Gnade Gottes<, die> mit mir <ist>*.", footnotes: ["℘ Eph 3,7.8; 1Tim 1,14", "℘ 2Kor 11,23", "℘ Kap. 3,10; 2Kor 3,5"] },
      { number: 11, text: "Ob nun ich oder jene: So <jedenfalls> predigen wir, und so seid ihr zum Glauben gekommen." },
      { number: 12, text: "Wenn aber gepredigt wird, dass Christus aus den Toten auferweckt* sei, wie sagen einige unter euch, dass es keine Auferstehung der Toten gebe*?", heading: "Die Auferstehungshoffnung gegen die Leugnung der Auferstehung", footnotes: ["o. auferweckt worden; die griech. Zeitform bezeichnet eine geschehene, in ihrer Wirkung fortdauernde Tatsache, so V. 13.14.16.17.20.", "℘ Apg 23,8"] },
      { number: 13, text: "Wenn es aber keine Auferstehung der Toten gibt, so ist auch Christus nicht auferweckt;" },
      { number: 14, text: "wenn aber Christus nicht auferweckt ist, so ist also auch unsere Predigt inhaltslos*, inhaltslos aber auch euer Glaube.", footnotes: ["w. leer, eitel"] },
      { number: 15, text: "Wir werden aber auch als falsche Zeugen Gottes befunden, weil wir gegen Gott bezeugt haben, dass er Christus auferweckt habe*, den er nicht auferweckt hat, wenn wirklich Tote nicht auferweckt werden.", footnotes: ["℘ Apg 13,30; 17,31"] },
      { number: 16, text: "Denn wenn Tote nicht auferweckt werden, so ist auch Christus nicht auferweckt*.", footnotes: ["℘ Kap. 6,14"] },
      { number: 17, text: "Wenn aber Christus nicht auferweckt ist, so ist euer Glaube nichtig, so seid ihr noch in euren Sünden*.", footnotes: ["℘ Apg 13,34-38; Röm 4,25"] },
      { number: 18, text: "Also sind auch die, welche in Christus entschlafen sind, verloren gegangen*.", footnotes: ["℘ 1Thes 4,14"] },
      { number: 19, text: "Wenn wir allein in diesem Leben auf Christus gehofft haben, so sind wir die elendesten von allen Menschen." },
      { number: 20, text: "Nun aber ist Christus aus <den> Toten auferweckt*, der Erstling der Entschlafenen*;", footnotes: ["℘ Mt 28,6; 2Tim 2,8; 1Petr 1,3", "℘ Kol 1,18"] },
      { number: 21, text: "denn da ja durch einen Menschen <der> Tod <kam>*, so auch durch einen Menschen <die> Auferstehung <der> Toten.", footnotes: ["℘ 1Mo 2,17; 3,19; Röm 5,12"] },
      { number: 22, text: "Denn wie in Adam alle sterben, so werden auch in Christus alle lebendig gemacht werden." },
      { number: 23, text: "Jeder aber in seiner eigenen Ordnung*: <der> Erstling, Christus*; sodann die, welche Christus gehören bei seiner Ankunft*;", footnotes: ["w. Abteilung (militärischer Ausdruck)", "℘ Apg 26,23", "℘ 1Thes 4,16; Offb 20,5"] },
      { number: 24, text: "dann das Ende, wenn er das Reich* dem Gott und Vater übergibt; wenn er alle Herrschaft und alle Gewalt und Macht weggetan hat.", footnotes: ["o. die Königsherrschaft"] },
      { number: 25, text: "Denn er muss herrschen*, bis er alle Feinde unter seine Füße gelegt hat*.", footnotes: ["o. König sein", "℘ Ps 110,1; Mt 22,44"] },
      { number: 26, text: "Als letzter Feind wird der Tod weggetan*.", footnotes: ["℘ Jes 25,8; Offb 20,14; 21,4"] },
      { number: 27, text: "»Denn alles hat er seinen Füßen unterworfen.«* Wenn es aber heißt, dass alles unterworfen sei, so ist klar, dass der ausgenommen ist, der ihm alles unterworfen hat.", footnotes: ["℘ Ps 8,7; Eph 1,22; Hebr 2,8"] },
      { number: 28, text: "Wenn ihm aber alles unterworfen ist*, dann wird auch der Sohn selbst dem unterworfen sein, der ihm alles unterworfen hat*, damit Gott alles in allem* sei*.", footnotes: ["℘ Eph 1,10; Phil 3,21", "℘ Kap. 11,3", "o. allen", "℘ Eph 4,6"] },
      { number: 29, text: "Was werden sonst die tun, die sich für die* Toten taufen lassen*? Wenn überhaupt Tote nicht auferweckt werden, warum lassen sie sich denn für sie taufen*?", footnotes: ["o. anstelle der; so auch nachher", "o. die für die Toten getauft werden", "o. werden sie denn für sie getauft"] },
      { number: 30, text: "Warum sind auch wir jede Stunde in Gefahr?" },
      { number: 31, text: "Täglich sterbe ich, so wahr ihr mein Ruhm seid*, Brüder, den ich in Christus Jesus, unserem Herrn, habe*.", footnotes: ["w. fürwahr, bei dem Ruhm euretwegen", "℘ Kap. 4,9; 2Kor 4,10.11"] },
      { number: 32, text: "Wenn ich <nur> nach Menschen<weise> mit wilden Tieren gekämpft habe zu Ephesus, was nützt es mir? Wenn Tote nicht auferweckt werden, so »lasst uns essen und trinken, denn morgen sterben wir«*!", footnotes: ["℘ Jes 22,13"] },
      { number: 33, text: "Irrt euch nicht: Schlechter Umgang verdirbt gute Sitten." },
      { number: 34, text: "Werdet in rechter Weise* nüchtern und sündigt nicht*! Denn manche sind in Unwissenheit über Gott; zur Beschämung sage ich es euch*.", footnotes: ["o. rechtschaffen; o. richtig", "℘ Ps 4,5; Eph 4,26", "℘ Kap. 6,5"] },
      { number: 35, text: "Es wird aber jemand sagen: Wie werden die Toten auferweckt? Und mit was für einem Leib kommen sie?", heading: "Die Auferstehungshoffnung und die Eigenart der Auferstehung" },
      { number: 36, text: "Tor! Was du säst, wird nicht lebendig, es sterbe denn*.", footnotes: ["℘ Joh 12,24"] },
      { number: 37, text: "Und was du säst, du säst nicht den Leib, der werden soll, sondern ein nacktes Korn, es sei von Weizen oder von einem der anderen <Samenkörner>." },
      { number: 38, text: "Gott aber gibt ihm einen Leib, wie er gewollt hat, und jedem der Samen seinen eigenen Leib*.", footnotes: ["℘ 1Mo 1,11.12"] },
      { number: 39, text: "Nicht alles Fleisch ist dasselbe Fleisch; sondern ein anderes <ist das> der Menschen und ein anderes das Fleisch des Viehes und ein anderes das der Vögel und ein anderes das der Fische." },
      { number: 40, text: "Und es gibt himmlische Leiber und irdische Leiber. Aber anders ist der Glanz* der himmlischen, anders der der irdischen;", footnotes: ["o. Herrlichkeit; so auch V. 41"] },
      { number: 41, text: "ein anderer der Glanz der Sonne und ein anderer der Glanz des Mondes und ein anderer der Glanz der Sterne, denn es unterscheidet sich Stern von Stern an Glanz." },
      { number: 42, text: "So ist auch die Auferstehung der Toten. Es wird gesät in Vergänglichkeit*, es wird auferweckt in Unvergänglichkeit.", footnotes: ["o. Verderben"] },
      { number: 43, text: "Es wird gesät in Unehre, es wird auferweckt in Herrlichkeit*; es wird gesät in Schwachheit, es wird auferweckt in Kraft;", footnotes: ["℘ Phil 3,21"] },
      { number: 44, text: "es wird gesät ein natürlicher* Leib, es wird auferweckt ein geistlicher Leib. Wenn es einen natürlichen Leib gibt, so gibt es auch einen geistlichen.", footnotes: ["o. seelischer; so auch nachher"] },
      { number: 45, text: "So steht auch geschrieben: »Der erste Mensch, Adam, wurde zu einer lebendigen Seele«*, der letzte Adam zu einem lebendig machenden Geist*.", footnotes: ["℘ 1Mo 2,7", "℘ Joh 5,21; Röm 5,14; 8,11; 2Kor 3,17"] },
      { number: 46, text: "Aber das Geistliche ist nicht zuerst, sondern das Natürliche*, danach das Geistliche.", footnotes: ["o. Seelische"] },
      { number: 47, text: "Der erste Mensch ist von der Erde, irdisch; der zweite Mensch vom Himmel*.", footnotes: ["℘ Joh 3,31"] },
      { number: 48, text: "Wie der Irdische, so sind auch die Irdischen; und wie der Himmlische, so sind auch die Himmlischen." },
      { number: 49, text: "Und wie wir das Bild des Irdischen getragen haben*, so werden wir auch das Bild des Himmlischen tragen*.", footnotes: ["℘ 1Mo 5,3", "℘ Röm 8,29"] },
      { number: 50, text: "Dies aber sage ich, Brüder, dass Fleisch und Blut das Reich* Gottes nicht erben können*, auch die Vergänglichkeit* nicht die Unvergänglichkeit erbt.", footnotes: ["o. die Königsherrschaft", "℘ Kap. 6,10; Joh 3,3", "o. Verderben"] },
      { number: 51, text: "Siehe, ich sage euch ein Geheimnis: Wir werden nicht alle entschlafen*, wir werden aber alle verwandelt werden*,", footnotes: ["℘ 1Thes 4,15", "℘ Phil 3,21"] },
      { number: 52, text: "in einem Nu, in einem Augenblick, bei der letzten Posaune; denn posaunen wird es, und die Toten werden auferweckt werden, unvergänglich <sein>, und wir werden verwandelt werden*.", footnotes: ["℘ 1Thes 4,16"] },
      { number: 53, text: "Denn dieses Vergängliche muss Unvergänglichkeit anziehen und dieses Sterbliche Unsterblichkeit anziehen*.", footnotes: ["℘ 2Kor 5,2-4; 2Tim 1,10"] },
      { number: 54, text: "Wenn aber dieses Vergängliche Unvergänglichkeit anziehen und dieses Sterbliche Unsterblichkeit anziehen wird, dann wird das Wort erfüllt werden, das geschrieben steht: »Verschlungen ist der Tod in Sieg.«*", heading: "Lobpreis Gottes im Blick auf die Auferstehungshoffnung", footnotes: ["℘ Jes 25,8"] },
      { number: 55, text: "»Wo ist, Tod, dein Sieg? Wo ist, Tod, dein Stachel?«*", footnotes: ["℘ Hos 13,14"] },
      { number: 56, text: "Der Stachel des Todes aber ist die Sünde*, die Kraft der Sünde aber das Gesetz*.", footnotes: ["℘ Röm 5,20", "℘ Röm 6,14; 7,8.13"] },
      { number: 57, text: "Gott aber sei Dank, der uns den Sieg gibt durch unseren Herrn Jesus Christus*!", footnotes: ["℘ Röm 7,25"] },
      { number: 58, text: "Daher, meine geliebten Brüder, seid fest*, unerschütterlich, allezeit überreich in dem Werk des Herrn, da ihr wisst, dass eure Mühe im Herrn nicht vergeblich ist*!", footnotes: ["℘ 2Thes 2,15", "℘ 2Chr 15,7"] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "Was aber die Sammlung für die Heiligen betrifft*, macht auch ihr es so, wie ich es für die Gemeinden* von Galatien angeordnet habe*!", heading: "Anweisung über Sammlungen für die Gemeinde in Jerusalem", footnotes: ["℘ Apg 11,29.30", "o. Versammlungen", "℘ 2Kor 8,7.11"] },
      { number: 2, text: "An jedem ersten Wochentag* lege ein jeder von euch bei sich zurück und sammle an, je nachdem er Gedeihen hat, damit nicht <erst> dann, wenn ich komme, Sammlungen geschehen.", footnotes: ["℘ Lk 24,1"] },
      { number: 3, text: "Wenn ich aber angekommen bin, so will ich solche, die ihr für bewährt haltet, mit Briefen senden, dass sie eure Gabe nach Jerusalem hinbringen*.", footnotes: ["℘ Apg 11,30; 2Kor 8,19"] },
      { number: 4, text: "Wenn es aber <der Mühe> wert ist, dass auch ich hinreise, so sollen sie mit mir reisen." },
      { number: 5, text: "Ich werde aber zu euch kommen, wenn ich Mazedonien durchzogen habe. Denn Mazedonien durchziehe ich <nur>*;", heading: "Reisepläne des Apostels", footnotes: ["℘ Apg 19,21"] },
      { number: 6, text: "bei euch aber werde ich vielleicht bleiben* oder auch überwintern, damit ihr mich geleitet*, wohin ich auch reise;", footnotes: ["℘ Apg 20,3", "℘ Röm 15,24; 2Kor 1,16; 3Jo 6"] },
      { number: 7, text: "denn ich will euch jetzt nicht im Vorbeigehen sehen, denn ich hoffe, einige Zeit bei euch zu bleiben, wenn der Herr es erlaubt*.", footnotes: ["℘ Kap. 4,19"] },
      { number: 8, text: "Ich werde aber bis Pfingsten* in Ephesus bleiben*,", footnotes: ["w. Tag des 50. (Tag nach Darbringung der Erstlingsgarbe); auch »Fest der Wochen« genannt", "℘ Apg 19,1"] },
      { number: 9, text: "denn eine große und wirksame Tür ist mir geöffnet worden*, und der Widersacher sind viele*.", footnotes: ["℘ Apg 14,27; 2Kor 2,12; Kol 4,3; Offb 3,8", "℘ 2Kor 1,8"] },
      { number: 10, text: "Wenn aber Timotheus kommt*, so seht zu, dass er ohne Furcht bei euch sei! Denn er arbeitet am Werk des Herrn wie auch ich*.", heading: "Mitteilungen über Mitarbeiter", footnotes: ["℘ Kap. 4,17", "℘ Röm 16,21"] },
      { number: 11, text: "Es verachte ihn nun niemand*. Geleitet* ihn aber in Frieden, dass er zu mir komme! Denn ich erwarte ihn mit den Brüdern.", footnotes: ["℘ 1Tim 4,12", "℘ V. 6"] },
      { number: 12, text: "Was aber den Bruder Apollos* betrifft, so habe ich ihm vielfach zugeredet, dass er mit den Brüdern zu euch komme; und es war durchaus* nicht <sein> Wille, jetzt zu kommen, doch wird er kommen, sobald er Gelegenheit findet.", footnotes: ["℘ Kap. 1,12", "o. allerdings"] },
      { number: 13, text: "Wachet*, steht fest im Glauben*; seid mannhaft, seid stark*!", footnotes: ["℘ Mt 24,42; Apg 20,31; 1Petr 5,8", "℘ 2Kor 1,24; Gal 5,1; Phil 4,1", "w. erstarkt\n℘ Eph 6,10"] },
      { number: 14, text: "Alles bei euch geschehe in Liebe*!", footnotes: ["℘ Kap. 14,40; Kol 3,14; 1Petr 4,8"] },
      { number: 15, text: "Ich ermahne* euch aber, Brüder: Ihr kennt das Haus des Stephanas*, dass es der Erstling von Achaja ist* und dass sie sich in den Dienst für die Heiligen gestellt haben*;", footnotes: ["o. bitte", "℘ Kap. 1,16", "℘ Röm 16,5", "℘ Hebr 6,10"] },
      { number: 16, text: "dass auch ihr euch solchen unterordnet und jedem, der mitwirkt und sich abmüht*.", footnotes: ["℘ Phil 2,29; 1Thes 5,12"] },
      { number: 17, text: "Ich freue mich aber über die Ankunft des Stephanas und Fortunatus und Achaikus, denn diese haben eure Abwesenheit ersetzt*.", footnotes: ["o. diese haben, woran ihr es fehlen ließet, ausgefüllt; o. diese haben, was euch fehlte, ausgefüllt\n℘ Phil 2,30"] },
      { number: 18, text: "Denn sie haben meinen und euren Geist erquickt*. Erkennt nun solche an*!", footnotes: ["℘ Phim 7", "℘ Phil 2,29; 1Thes 5,12"] },
      { number: 19, text: "Es grüßen euch die Gemeinden* Asiens*. Es grüßen euch vielmals im Herrn Aquila und Priska* samt der Gemeinde in ihrem Hause*.", heading: "Grüße und Segenswunsch", footnotes: ["o. Versammlungen; so auch nachher", "d. i. die röm. Provinz Asien; vgl. auch Anm. zu Apg 16,6", "℘ Apg 18,2", "℘ Röm 16,3-5"] },
      { number: 20, text: "Es grüßen euch die Brüder alle*. Grüßt einander mit heiligem Kuss*!", footnotes: ["℘ 2Kor 13,12; Tit 3,15", "℘ Röm 16,16"] },
      { number: 21, text: "Der Gruß mit meiner, des Paulus, Hand*.", footnotes: ["℘ Gal 6,11; Kol 4,18; 2Thes 3,17"] },
      { number: 22, text: "Wenn jemand den Herrn nicht lieb hat, der sei verflucht*! Maranatha!*", footnotes: ["griech. anathema; d. h. dem Gericht Gottes übergeben\n℘ Gal 1,8.9", "aram.; bedeutet »Der Herr ist gekommen.« o. »Unser Herr, komm!«"] },
      { number: 23, text: "Die Gnade des Herrn Jesus <sei> mit euch*!", footnotes: ["℘ Röm 16,20"] },
      { number: 24, text: "Meine Liebe <sei> mit euch allen in Christus Jesus*!", footnotes: ["℘ 2Kor 11,11"] },
    ]},
  ]
};
